#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

int main(void) {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Open GPIO 2 and GPIO 3
    struct gpiod_device *gpiodev;
    int ret = gpiod_get_device_by_name("gpiochip0", &gpiodev);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO device: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO pins
    int gpio2_fd = gpiod_open(gpiodev, "gpio2", GPIOD_OPEN_OUTPUT);
    int gpio3_fd = gpiod_open(gpiodev, "gpio3", GPIOD_OPEN_OUTPUT);

    if (gpio2_fd < 0 || gpio3_fd < 0) {
        fprintf(stderr, "Error opening GPIO pins: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_close(gpiodev);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 high
        if (gpiod_set_value(gpio2_fd, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 2 high: %s\n", gpiod_errstr(gpiod_get_error()));
            break;
        }
        printf("GPIO 2 set high\n");

        // Set GPIO 3 low
        if (gpiod_set_value(gpio3_fd, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 3 low: %s\n", gpiod_errstr(gpiod_get_error()));
            break;
        }
        printf("GPIO 3 set low\n");

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up GPIO pins
    gpiod_close(gpio2_fd);
    gpiod_close(gpio3_fd);

    // Close the GPIO device
    gpiod_close(gpiodev);

    // Cleanup libgpiod
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

