#include <gpiod.h>

#define GPIO_NUM 2  // BCM GPIO 2

int main(void) {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Open GPIO 2 in output mode
    struct gpiod_dir *dir;
    if ((dir = gpiod_get_direction(GPIO_NUM)) == NULL) {
        fprintf(stderr, "Failed to get direction of GPIO %u: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_set_direction(GPIO_NUM, GPIOD_OUT_HIGH) < 0) {
        fprintf(stderr, "Failed to set GPIO %u to output: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
        gpiod_free(dir);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 high
        if (gpiod_set_value(GPIO_NUM, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %u high: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
            break; // Exit loop on error
        }

        // Wait for 5 seconds
        sleep(5);

        // Set GPIO 2 low
        if (gpiod_set_value(GPIO_NUM, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %u low: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
            break; // Exit loop on error
        }

        // Check if the GPIO value read is valid
        if (gpiod_get_value(GPIO_NUM) == 0) {
            printf("GPIO %u is low\n", GPIO_NUM);
        } else {
            printf("GPIO %u is high\n", GPIO_NUM);
        }
    }

    // Clean up
    gpiod_free(dir);
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

