#include <stdint.h>
#include <errno.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERTTEMP_L 0x00
#define ADS1115_REG_CONVERTTEMP_H 0x01
#define ADS1115_REG_CONVERTAIN0_L 0x02
#define ADS1115_REG_CONVERTAIN0_H 0x03

#define I2C_DEVICE_PATH "/dev/i2c-1" // Adjust according to your Raspberry Pi's I2C bus

int main() {
    int fd;
    int result;
    uint16_t temp_l, temp_h, adc_value;

    // Open I2C device
    fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Check if device is accessible
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) == -1) {
        perror("Failed to access I2C slave");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Initialize variables
    temp_l = 0;
    temp_h = 0;
    adc_value = 0;

    while (1) {
        // Read temperature LSB and MSB
        result = read(fd, &temp_l, 1);
        if (result != 1) {
            perror("Failed to read temperature LSB");
            break;
        }
        result = read(fd, &temp_h, 1);
        if (result != 1) {
            perror("Failed to read temperature MSB");
            break;
        }

        // Calculate combined temperature value
        temp_l = (temp_l << 8) | temp_h;
        temp_l = (temp_l >> 4) & 0x0F; // Extract temperature value

        // Read ADC value
        result = read(fd, &adc_value, 2);
        if (result != 2) {
            perror("Failed to read ADC value");
            break;
        }

        // Print readings
        printf("Temperature (°C): %.2f\n", temp_l / 16.0);
        printf("ADC Value: %hu\n", adc_value);

        // Sleep for 0.5 seconds
        usleep(500000);

        // Close I2C device on interrupt (Ctrl+C)
        if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
            perror("Failed to ignore SIGINT");
            break;
        }
    }

    // Close I2C device and release resources
    close(fd);
    return 0;
}

