#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERTTEMP_L 0x00
#define ADS1115_REG_CONVERTTEMP_H 0x01
#define ADS1115_REG_CONVERTVOLTAGE 0x02

#define I2C_DEVICE "/dev/i2c-1" // Adjust according to your Raspberry Pi's I2C bus

int main() {
    int fd;
    int result;
    uint16_t tempLow, tempHigh, voltage;
    struct i2c_msg msg[3];

    // Open I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Prepare I2C messages
    msg[0].addr = ADS1115_ADDR;
    msg[0].len = sizeof(uint8_t);
    msg[0].buf = (uint8_t *) &ADS1115_REG_CONVERTTEMP_L;

    msg[1].addr = ADS1115_ADDR;
    msg[1].len = sizeof(uint16_t);
    msg[1].buf = (uint8_t *) &tempHigh;

    msg[2].addr = ADS1115_ADDR;
    msg[2].len = sizeof(uint16_t);
    msg[2].buf = (uint8_t *) &tempLow;

    // Write register addresses
    result = i2c_master_send(fd, msg, sizeof(msg) / sizeof(msg[0]));
    if (result < 0) {
        perror("Failed to write to ADS1115");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Read temperature low
    result = i2c_master_recv(fd, msg, 2, sizeof(msg[0]));
    if (result < 0) {
        perror("Failed to read temperature low");
        close(fd);
        exit(EXIT_FAILURE);
    }

    tempLow = msg[0].buf[0] << 8 | msg[0].buf[1];

    // Read temperature high
    result = i2c_master_recv(fd, msg, 1, sizeof(msg[0]));
    if (result < 0) {
        perror("Failed to read temperature high");
        close(fd);
        exit(EXIT_FAILURE);
    }

    tempHigh = msg[1].buf[0] << 8 | msg[1].buf[1];

    // Calculate temperature in degrees Celsius
    float temperatureCelsius = (tempHigh - tempLow) / 131.0; // ADS1115 conversion factor

    // Read voltage
    msg[0].addr = ADS1115_ADDR;
    msg[0].len = sizeof(uint8_t);
    msg[0].buf = (uint8_t *) &ADS1115_REG_CONVERTVOLTAGE;

    result = i2c_master_send(fd, msg, sizeof(msg) / sizeof(msg[0]));
    if (result < 0) {
        perror("Failed to write to ADS1115");
        close(fd);
        exit(EXIT_FAILURE);
    }

    result = i2c_master_recv(fd, msg, 1, sizeof(msg[0]));
    if (result < 0) {
        perror("Failed to read voltage");
        close(fd);
        exit(EXIT_FAILURE);
    }

    voltage = msg[0].buf[0];

    // Print readings
    printf("Temperature (°C): %.2f\n", temperatureCelsius);
    printf("Voltage: %d mV\n", voltage * 1000);

    // Close I2C device and release resources
    close(fd);

    return 0;
}

