#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Function prototypes
void setup_gpios(void);
void measure_distance(void);
void cleanup_gpios(void);
void handle_signal(int signum);

int main(void) {
    // Initialize GPIO
    setup_gpios();

    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handle_signal);

    while (1) {
        // Measure distance every 60 seconds
        struct timespec timeout = { .tv_sec = 60, .tv_nsec = 0 };
        measure_distance();

        usleep(1000000); // Wait for 1 second
    }

    // Clean up GPIO on exit
    cleanup_gpios();

    return 0;
}

// Function to set up GPIO pins
void setup_gpios(void) {
    int trigger_pin = gpiod_get_index(TRIGGER_PIN);
    int echo_pin = gpiod_get_index(ECHO_PIN);

    if (trigger_pin == -1 || echo_pin == -1) {
        fprintf(stderr, "Error: GPIO pins not found\n");
        exit(EXIT_FAILURE);
    }

    gpiod_direction_output(trigger_pin, 1); // Set trigger pin to output
    gpiod_direction_output(echo_pin, 0);   // Set echo pin to input

    if (gpiod_is_valid(trigger_pin) == 0 || gpiod_is_valid(echo_pin) == 0) {
        fprintf(stderr, "Error: GPIO pins are not valid\n");
        exit(EXIT_FAILURE);
    }
}

// Function to measure distance using HC-SR04
void measure_distance(void) {
    int start_time;
    int echo_time;

    // Trigger the ultrasonic sensor
    gpiod_write(trigger_pin, 1);

    // Wait for the echo pin to go high
    start_time = clock_gettime(CLOCK_MONOTONIC, &start_time);
    while (gpiod_read(echo_pin) == 0) {
        // Timeout after 10ms (worst-case scenario for HC-SR04)
        if (clock_gettime(CLOCK_MONOTONIC, &start_time) - start_time > 10000) {
            fprintf(stderr, "Error: Device did not respond\n");
            exit(EXIT_FAILURE);
        }
    }

    // Read the echo pin
    echo_time = clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Calculate the distance
    int distance = (echo_time - start_time) * 17150; // Assuming speed of sound is 17150 cm/µs

    printf("Distance: %d cm\n", distance);
}

// Function to cleanup GPIO resources
void cleanup_gpios(void) {
    gpiod_set_direction(trigger_pin, GPIOD_DIR_INPUT);
    gpiod_set_direction(echo_pin, GPIOD_DIR_INPUT);

    gpiod_unexport_all();
}

// Signal handler to catch SIGINT (Ctrl+C)
void handle_signal(int signum) {
    fprintf(stderr, "Caught SIGINT, exiting...\n");
    exit(EXIT_FAILURE);
}

