    ret = gpiod_set_direction(direction, GPIOD_DIR_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting direction: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_dir_free(direction);
        gpiod_dir_free(cand);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Toggle the state of GPIO 18
    while (1) {
        // Set GPIO 18 high
        ret = gpiod_set_value(direction, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO high: %s\n", gpiod_errstr(gpiod_get_error()));
            gpiod_dir_free(direction);
            gpiod_dir_free(cand);
            gpiod_cleanup();
            return EXIT_FAILURE;
        }

