int main(void) {
    // Check if the gpiod library is available
    if (gpiod_is_valid()) {
        // Open GPIO device
        int gpio_dev = gpiod_open(GPIOD_DIR_DEV, "gpiochip0");
        if (gpio_dev < 0) {
            fprintf(stderr, "Error opening GPIO device: %s\n", gpiod_errstr(gpio_dev));
            return 1; // Exit with error if opening fails
        }

        // Find GPIO pin 18 (BCM numbering)
        int gpio_pin = gpiod_find_pin(gpio_dev, "P18");
        if (gpio_pin < 0) {
            fprintf(stderr, "Error finding GPIO pin 18: %s\n", gpiod_errstr(gpio_pin));
            gpiod_close(gpio_dev);
            return 1; // Exit with error if pin not found
        }

        // Set up the GPIO pin for output
        if (gpiod_direction_output(gpio_pin, 1) < 0) {
            fprintf(stderr, "Error setting GPIO pin 18 to output: %s\n", gpiod_errstr(gpio_pin));
            gpiod_close(gpio_dev);
            return 1; // Exit with error if direction fails
        }

        // Main loop for 3 cycles, each 2 seconds apart
        for (int i = 0; i < 3; ++i) {
            // Set GPIO pin high
            if (gpiod_write(gpio_pin, 1) < 0) {
                fprintf(stderr, "Error setting GPIO pin 18 high: %s\n", gpiod_errstr(gpio_pin));
                gpiod_close(gpio_dev);
                return 1; // Exit with error if write fails
            }

            // Wait for 2 seconds
            sleep(2);

            // Set GPIO pin low
            if (gpiod_write(gpio_pin, 0) < 0) {
                fprintf(stderr, "Error setting GPIO pin 18 low: %s\n", gpiod_errstr(gpio_pin));
                gpiod_close(gpio_dev);
                return 1; // Exit with error if write fails
            }

            // Wait for 1 second
            sleep(1);
        }

        // Close the GPIO device
        gpiod_close(gpio_dev);

        // Exit successfully
        return 0;
    } else {
        // Report that libgpiod is not available
        fprintf(stderr, "libgpiod is not available.\n");
        return 1; // Exit with error if libgpiod is not available
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION_RESULT_low 0x00
#define ADS1115_REG_CONVERSION_RESULT_high 0x01

int main() {
    // Open the I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Check if device was opened successfully
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to change I2C address");
        close(fd);
        return EXIT_FAILURE;
    }

    // Structure to hold conversion result
    uint16_t conversion_result;

    // Read low byte of conversion result
    if (read(fd, &conversion_result, 1) != 1) {
        perror("Failed to read low byte of conversion result");
        close(fd);
        return EXIT_FAILURE;
    }

    // Read high byte of conversion result
    if (read(fd, &conversion_result, 1) != 1) {
        perror("Failed to read high byte of conversion result");
        close(fd);
        return EXIT_FAILURE;
    }

    // Combine the two bytes to get the full conversion result
    conversion_result = (uint16_t)(conversion_result << 8) | (uint16_t)conversion_result;

    // Print the conversion result
    printf("Analog reading: %hu\n", conversion_result);

    // Close the I2C device
    close(fd);

    return EXIT_SUCCESS;
}

