    if (gpiod_direction_output(fd, 1) < 0) {
        perror("gpiod_direction_output");
        gpiod_close(fd);
        gpiod_cleanup();
        return 1;
    }

    // Attempt to write to the GPIO pin
    int state = 1; // Set the state to high (1)
    if (gpiod_write(fd, &state, sizeof(state)) < 0) {
        perror("gpiod_write");
        gpiod_close(fd);
        gpiod_cleanup();
        return 1;
    }

    // Read the current state of the GPIO pin
    int read_state;
    if (gpiod_read(fd, &read_state, sizeof(read_state)) < 0) {
        perror("gpiod_read");
        gpiod_close(fd);
        gpiod_cleanup();
        return 1;
