    printf("Applied state: %d (High)\n", state);

    // Reset the GPIO pin to its default state
    if (gpiod_write(fd, NULL, 0) < 0) {
        perror("gpiod_write (reset)");
        gpiod_close(fd);
        gpiod_cleanup();
        return 1;
    }

    // Close the GPIO device file descriptor
