#define GPIO_NUM_4  7
#define GPIO_NUM_18 10

int main() {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Open GPIO controller
    struct gpiod_device *gpiodev;
    if ((gpiodev = gpiod_get_device_by_name("bcm2835-gpio")) == NULL) {
        fprintf(stderr, "Error: GPIO device not found.\n");
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO pins
    int fd_gpio4 = gpiod_open(gpiodev, GPIO_NUM_4, GPIOD_OPEN_DUPLEX);
    int fd_gpio18 = gpiod_open(gpiodev, GPIO_NUM_18, GPIOD_OPEN_DUPLEX);

    if (fd_gpio4 < 0 || fd_gpio18 < 0) {
        fprintf(stderr, "Error opening GPIO pins: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_close(fd_gpio4);
        gpiod_close(fd_gpio18);
        gpiod_device_put(gpiodev);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Function to toggle the GPIO state
    void toggle_gpio(int fd, int gpio_num) {
        int state = gpiod_get(fd, gpio_num, GPIOD_INPUT);
        if (state == GPIOD_STATE_HIGH) {
            gpiod_set(fd, gpio_num, GPIOD_OUTPUT, 1);
            gpiod_write(fd, gpio_num, 0);
        } else {
            gpiod_set(fd, gpio_num, GPIOD_OUTPUT, 0);
            gpiod_write(fd, gpio_num, 1);
        }
    }

    // Main loop
    while (1) {
        // Toggle GPIO 4
        toggle_gpio(fd_gpio4, GPIO_NUM_4);

        // Toggle GPIO 18
        toggle_gpio(fd_gpio18, GPIO_NUM_18);

        // Sleep for 0.05 seconds
        usleep(50000);
    }

    // Cleanup on interrupt (e.g., Ctrl+C)
    if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
        fprintf(stderr, "Error ignoring SIGINT: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Handle interrupt by cleaning up
    signal(SIGINT, SIG_DFL);

    // Close GPIO pins and release the GPIO controller
    gpiod_close(fd_gpio4);
    gpiod_close(fd_gpio18);
    gpiod_device_put(gpiodev);
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

