#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define SI7021_ADDR 0x40
#define SI7021_REG_TEMP 0x88
#define SI7021_REG_HUMID 0x89

int main() {
    int fd;
    struct i2c_msg msg[2];
    int ret;
    uint16_t temperature;
    uint16_t humidity;

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Prepare I2C messages
    msg[0].addr = SI7021_ADDR;
    msg[0].len = sizeof(uint8_t);
    msg[0].buf = (uint8_t *) &SI7021_REG_TEMP;

    msg[1].addr = SI7021_ADDR;
    msg[1].len = sizeof(uint8_t);
    msg[1].buf = (uint8_t *) &SI7021_REG_HUMID;

    // Loop indefinitely, exit on interrupt
    while (1) {
        // Send I2C commands
        ret = i2c_master_send(fd, msg, sizeof(msg));
        if (ret != sizeof(msg)) {
            perror("Failed to send I2C commands");
            close(fd);
            return EXIT_FAILURE;
        }

        // Receive temperature data
        ret = i2c_master_recv(fd, msg, sizeof(msg));
        if (ret != sizeof(msg)) {
            perror("Failed to receive temperature data");
            close(fd);
            return EXIT_FAILURE;
        }
        temperature = msg[0].buf[0] << 8 | msg[0].buf[1];

        // Receive humidity data
        ret = i2c_master_recv(fd, msg, sizeof(msg));
        if (ret != sizeof(msg)) {
            perror("Failed to receive humidity data");
            close(fd);
            return EXIT_FAILURE;
        }
        humidity = msg[1].buf[0] << 8 | msg[1].buf[1];

        // Check if the device is valid
        if ((temperature > 0xFFFF || temperature < 0) || (humidity > 0xFFFF || humidity < 0)) {
            fprintf(stderr, "Invalid temperature or humidity reading\n");
            close(fd);
            return EXIT_FAILURE;
        }

        // Print readings
        printf("Temperature: %hu°C\n", temperature);
        printf("Humidity: %hu%\n", humidity);

        // Sleep for 5 seconds
        sleep(5);

        // Close the I2C device on interrupt (Ctrl+C)
        if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
            perror("Failed to ignore SIGINT");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Close the I2C device on exit
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERTTEMP_L 0x00
#define ADS1115_REG_CONVERTTEMP_H 0x01
#define ADS1115_REG_CONVERTAIN0 0x02
#define ADS1115_REG_CONVERTAIN1 0x03

int main() {
    int fd;
    int result;
    struct i2c_msg msg[3];
    uint8_t data[12];
    int count = 0;

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Prepare I2C messages
    msg[0].addr = ADS1115_ADDR;
    msg[0].len = sizeof(uint16_t);
    msg[0].buf = (uint8_t *)&data[0];

    msg[1].addr = ADS1115_ADDR;
    msg[1].len = sizeof(uint16_t);
    msg[1].buf = (uint8_t *)&data[2];

    msg[2].addr = ADS1115_ADDR;
    msg[2].len = sizeof(uint16_t);
    msg[2].buf = (uint8_t *)&data[4];

    // Perform the I2C transactions
    for (int i = 0; i < 3; ++i) {
        result = i2c_transfer(fd, msg + i, 3);
        if (result != 3) {
            printf("Error reading from ADS1115: %d\n", result);
            close(fd);
            return EXIT_FAILURE;
        }

        // Convert the raw data to temperature or ADC values
        if (data[0] == 0x00) { // Convert TEMP_L
            uint16_t temp_l = (data[1] << 8) | data[2];
            float temp_c = (temp_l / 4.0) - 273.15;
            printf("TEMP_L: %.2f°C\n", temp_c);
        } else if (data[0] == 0x01) { // Convert TEMP_H
            uint16_t temp_h = (data[1] << 8) | data[2];
            float temp_c = (temp_h / 4.0) - 273.15;
            printf("TEMP_H: %.2f°C\n", temp_c);
        } else { // Convert ADC values
            uint16_t adc_value = (data[1] << 8) | data[2];
            printf("ADC Value: %hu\n", adc_value);
        }

        // Sleep for 1 second before the next reading
        sleep(1);
        ++count;
    }

    // Close the I2C device and release resources
    close(fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
