#include <gpiod.h>

#define GPIO_NUMS 6 // GPIO 8, 9, 10, 11, 23, 24
#define GPIO_MODE_OUT
#define GPIO_TRIGGER_ONESHOT

int main() {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        return EXIT_FAILURE;
    }

    // Open GPIO devices
    int fd = -1;
    for (int i = 8; i <= 24; i++) {
        if (gpiod_open(i, GPIO_MODE_OUT | GPIO_TRIGGER_ONESHOT) < 0) {
            perror("gpiod_open");
            return EXIT_FAILURE;
        }
        fd++;
    }

    // Ensure we have opened the correct number of GPIOs
    if (fd != GPIO_NUMS) {
        perror("Failed to open required GPIOs");
        gpiod_close(fd); // Close any opened GPIOs
        return EXIT_FAILURE;
    }

    // Main loop for 256 cycles
    for (int cycle = 0; cycle < 256; cycle++) {
        // Toggle the state of each GPIO
        for (int i = 0; i < GPIO_NUMS; i++) {
            int ret = gpiod_set_value(fd+i, !gpiod_get_value(fd+i));
            if (ret < 0) {
                perror("gpiod_set_value");
                break; // Exit loop if any GPIO fails
            }
        }

        // Output the state of each GPIO
        for (int i = 0; i < GPIO_NUMS; i++) {
            int state = gpiod_get_value(fd+i);
            printf("GPIO %d: %s\n", i + 8, state ? "HIGH" : "LOW");
        }

        // Sleep for a short period to control the cycle rate
        usleep(100000); // 100 milliseconds
    }

    // Close all GPIOs and clean up
    for (int i = 0; i < GPIO_NUMS; i++) {
        gpiod_close(fd+i);
    }
    gpiod_exit();

    return EXIT_SUCCESS;
}

