#include <sys/stat.h>

#define SERIAL_PORT "/dev/ttyAMA0" // Adjust according to your Raspberry Pi's serial port

int main() {
    int fd; // File descriptor for the serial port
    struct termios options; // Option settings for the serial port
    char buffer[256]; // Buffer for reading from the serial port

    // Open the serial port
    fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Get the current terminal settings
    tcgetattr(fd, &options);

    // Set the options: no parity, 8 bits, 1 stop bit, no flow control
    options.c_cflag = (options.c_cflag & ~PARENB & ~CSTOPB & ~CSIZE) | CS8 | CREAD;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    // Set the new options
    tcsetattr(fd, TCSANOW, &options);

    // Loop to read and print data from the serial port
    while (1) {
        // Read data from the serial port
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            perror("read");
            break; // Exit loop on error
        }

        // Print the received data
        printf("Received: %s\n", buffer);

        // Check if we should exit (e.g., Ctrl+C)
        if (bytes_read == 0) {
            break; // Exit loop on end of input
        }
    }

    // Close the serial port
    close(fd);

    // Release the serial port resources
    tcsetattr(fd, TCSAFLUSH, &options);

    return EXIT_SUCCESS;
}

