#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>

#define OPT3001_ADDR 0x44

// Structure for OPT3001 register definitions
typedef struct {
    uint8_t Register;
    uint8_t Mask;
    uint8_t StartAddress;
} OPT3001_REG;

// OPT3001 register definitions
static const OPT3001_REG OPT3001_REGISTERS[] = {
    {0x00, 0x00, 0x00}, // Register 0x00 - Power Control
    {0x01, 0x01, 0x00}, // Register 0x01 - Gain Control
    {0x02, 0x03, 0x00}, // Register 0x02 - Integration Time
    {0x03, 0x07, 0x00}, // Register 0x03 - Zero Point
    {0x04, 0x0F, 0x00}, // Register 0x04 - Calibration
    {0x05, 0x0F, 0x00}, // Register 0x05 - Temperature
    {0x06, 0x0F, 0x00}, // Register 0x06 - Ambient Light
    {0x07, 0x0F, 0x00}, // Register 0x07 - Light Measurement
};

// Function prototypes
void i2c_open();
void i2c_close();
int i2c_read(uint8_t address, uint8_t register_address, uint8_t* data);
void print_light_level(uint16_t light_level);

int main() {
    // Open the I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C communication
    i2c_open(fd);

    // Loop indefinitely to read and print light levels
    while (1) {
        uint8_t register_address = 0x07; // Light measurement register
        uint8_t data[2]; // Data buffer for light level reading

        // Read light level from OPT3001
        if (i2c_read(OPT3001_ADDR, register_address, data) != 2) {
            perror("Failed to read light level");
            break; // Exit loop on error
        }

        // Convert raw light level to lux
        uint16_t lux = (data[0] << 8) | data[1];
        print_light_level(lux);

        // Sleep for 1 second to avoid excessive CPU usage
        usleep(1000000);
    }

    // Close I2C device and release resources
    i2c_close();
    close(fd);

    return EXIT_SUCCESS;
}

// Function to open I2C communication
void i2c_open(int fd) {
    struct i2c_msg msg = {
        .addr = OPT3001_ADDR,
        .flags = 0
    };

    // Send START condition
    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to change I2C slave address");
    }

    // Prepare message for reading
    msg.len = 2; // 2 bytes to read
}

// Function to read data from the I2C device
int i2c_read(uint8_t address, uint8_t register_address, uint8_t* data) {
    struct i2c_msg msg = {
        .addr = address,
        .flags = 0,
        .len = 2
    };

    // Send START condition
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to change I2C slave address");
        return -1;
    }

    // Send the register address and read data
    msg.data = &register_address;
    if (ioctl(fd, I2C_READ, &msg) != 2) {
        perror("Failed to read data");
        return -1;
    }

    // Read the actual data
    if (ioctl(fd, I2C_READ, data) != 2) {
        perror("Failed to read data");
        return -1;
    }

    return 2; // Success
}

// Function to print the light level in lux
void print_light_level(uint16_t lux) {
    printf("Light level: %d lux\n", lux);
}

