        if (gpio_dev < 0) {
            fprintf(stderr, "Failed to open GPIO device: %s\n", gpiod_errstr(gpio_dev));
            return 1; // Exit with error
        }

        // Open GPIO line 4 (BCM 4, physical 7)
        int gpio_line = gpiod_open(gpio_dev, "4");
        if (gpio_line < 0) {
            fprintf(stderr, "Failed to open GPIO line 4: %s\n", gpiod_errstr(gpio_line));
            gpiod_close(gpio_dev);
            return 1; // Exit with error
        }

        // Set GPIO 4 to output mode
        if (gpiod_direction_output(gpio_line, 1)) {
            fprintf(stderr, "Failed to set GPIO 4 to output: %s\n", gpiod_errstr(gpio_line));
            gpiod_close(gpio_line);
            gpiod_close(gpio_dev);
            return 1; // Exit with error
        }

        // Write logic high to GPIO 4
        if (gpiod_write(gpio_line, 1)) {
            fprintf(stderr, "Failed to write logic high to GPIO 4: %s\n", gpiod_errstr(gpio_line));
            gpiod_close(gpio_line);
            gpiod_close(gpio_dev);
            return 1; // Exit with error
        }

        // Read the current state of GPIO 4
        int state = gpiod_read(gpio_line);
        if (state != 1) {
            fprintf(stderr, "GPIO 4 state is %d, expected 1\n", state);
