            gpiod_close(gpio_dev);
            return 1; // Exit with error
        }

        // Report the state applied
        printf("Successfully set GPIO 4 to high (state: %d)\n", state);

        // Release the GPIO line and device
        gpiod_close(gpio_line);
        gpiod_close(gpio_dev);

        return 0; // Success
    } else {
        // GPIO library is not available
        fprintf(stderr, "libgpiod is not available.\n");
        return 1; // Exit with error
    }
}

