int main(void) {
    struct gpiod_dir gpio_dir;
    struct gpiod_cand gpio_cand;
    int ret;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_errstr(ret));
        return EXIT_FAILURE;
    }

    // Open GPIO 2 for output
    ret = gpiod_open(GPIO_NUM, GPIOD_OPEN_DIR_OUT, &gpio_dir);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", GPIO_NUM, gpiod_errstr(ret));
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set GPIO 2 to active high
    ret = gpiod_set_direction(gpio_dir.dev, GPIOD_DIR_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction: %s\n", GPIO_NUM, gpiod_errstr(ret));
        gpiod_close(&gpio_dir);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Perform 3 cycles, each 60 seconds apart
    for (int i = 0; i < 3; ++i) {
        // Set GPIO high
        ret = gpiod_set_value(gpio_dir.dev, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_NUM, gpiod_errstr(ret));
            gpiod_close(&gpio_dir);
            gpiod_exit();
            return EXIT_FAILURE;
        }

        // Wait for 60 seconds
        sleep(60);

        // Read the GPIO value
        ret = gpiod_get_value(gpio_dir.dev, &gpio_cand);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO %d value: %s\n", GPIO_NUM, gpiod_errstr(ret));
            gpiod_close(&gpio_dir);
            gpiod_exit();
            return EXIT_FAILURE;
        }

        // Check if the read value is valid (should be 1 for active high)
        if (gpio_cand.value != 1) {
            fprintf(stderr, "Invalid GPIO value read: %d\n", gpio_cand.value);
            gpiod_close(&gpio_dir);
            gpiod_exit();
            return EXIT_FAILURE;
        }

        // Output the state applied
        printf("GPIO %d set to HIGH\n", GPIO_NUM);
    }

    // Close the GPIO device and exit
    gpiod_close(&gpio_dir);
    gpiod_exit();

    return EXIT_SUCCESS;
}

