int main() {
    int fd;
    w1_slave_config cfg;
    w1_slave *slv;
    float temperature;

    // Initialize w1_slave
    if ((fd = open(DS18B20_DEVICE, O_RDWR)) == -1) {
        perror("Failed to open DS18B20 device");
        exit(EXIT_FAILURE);
    }

    // Configure w1_slave
    cfg_family = W1_family_28;
    cfg.address = 0x28;
    if (w1_slave_init(fd, &cfg) < 0) {
        perror("Failed to initialize w1_slave");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Read and check temperature repeatedly
    while (1) {
        slv = w1_slave_read(fd);
        if (slv == NULL) {
            perror("Failed to read DS18B20");
            close(fd);
            exit(EXIT_FAILURE);
        }

        // Check if conversion was successful
        if (slv->res == -128) {
            printf("Temperature reading failed.\n");
            continue;
        }

        // Parse temperature from the result string
        char res[9];
        strncpy(res, slv->res, 8);
        res[8] = '\0';
        if (sscanf(res, "t=%f", &temperature) != 1) {
            printf("Invalid temperature reading.\n");
            continue;
        }

        // Print valid temperature
        printf("Temperature: %.1f°C\n", temperature);

        // Sleep for 5 seconds
        sleep(5);

        // Release resources
        w1_slave_free(slv);
        close(fd);
        break; // Exit loop on interrupt
    }

    // Clean up on exit
    w1_slave_uninit();

    return 0;
}

