    // Open I2C device
    fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Allocate I2C client structure
    client = i2c_new_clientfd(fd);
    if (client == NULL) {
        perror("Failed to allocate I2C client");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Check if the device exists
    if (!device_exists()) {
        printf("HTU21D sensor not found.\n");
        i2c_del_clientdata(client);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Read data from HTU21D
        if (htu21d_read(client, &data) == false) {
            printf("Failed to read from HTU21D.\n");
            break;
        }

        // Check if reading is valid
        if (data.humidity > 0xFF || data.temperature > 0xFF) {
            printf("Invalid HTU21D reading.\n");
            continue;
        }

        // Print valid reading
        printf("Humidity: %hu%%, Temperature: %hu°C\n", data.humidity, data.temperature);

        // Sleep for 60 seconds
        sleep(60);
    }

    // Release resources
    i2c_del_clientdata(client);
    close(fd);

    return 0;
}

// Function to read data from HTU21D
bool htu21d_read(struct i2c_client *client, struct htu21d_data *data) {
    uint8_t register_address = HTU21D_REG_MEASUREMENT;
    int bytes_read;

    // Write to register address
    if (i2c_smbus_write_byte_data(client, HTU21D_ADDR, register_address) != 0) {
        return false;
    }

    // Read data from register
    bytes_read = i2c_smbus_read_byte_data(client, HTU21D_ADDR);
    if (bytes_read != 1) {
        return false;
    }

    // Copy data from buffer to structure
    data->humidity = i2c_smbus_read_byte(client);
    data->temperature = i2c_smbus_read_byte(client);

    return true;
}

// Function to check if the device exists
bool device_exists(void) {
    int fd;
    struct stat st;

    fd = open(I2C_DEVICE_PATH, O_RDONLY);
    if (fd == -1) {
        return false;
    }

    if (fstat(fd, &st) == 0 && S_ISCHR(st.st_mode)) {
        close(fd);
        return true;
    }

    close(fd);
    return false;
}

