#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/time.h>

#define I2C_DEVICE_PATH "/dev/i2c-1" // Adjust according to your Raspberry Pi's I2C bus

#define ADXL345_REG_ACCEL_XOUT_H      0x32
#define ADXL345_REG_ACCEL_XOUT_L      0x33
#define ADXL345_REG_ACCEL_YOUT_H      0x34
#define ADXL345_REG_ACCEL_YOUT_L      0x35
#define ADXL345_REG_ACCEL_ZOUT_H      0x36
#define ADXL345_REG_ACCEL_ZOUT_L      0x37

#define ADXL345_ADDR 0x53

int main() {
    int fd;
    struct timeval tv;
    struct timespec ts;
    uint8_t data[6];
    int i;

    // Open I2C device
    fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Configure I2C device
    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to acquire I2C slave");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read data from ADXL345
        if (ioctl(fd, I2C_READ, (char *) &ADXL345_REG_ACCEL_XOUT_H) < 0) {
            perror("Failed to read accelerometer data");
            close(fd);
            exit(EXIT_FAILURE);
        }

        // Read 6 bytes for full accelerometer data
        for (i = 0; i < 6; i++) {
            if (ioctl(fd, I2C_READ, (char *) &data[i]) < 0) {
                perror("Failed to read accelerometer data");
                close(fd);
                exit(EXIT_FAILURE);
            }
        }

        // Convert data to integer values
        uint16_t acc_x = (data[0] << 8) | data[1];
        uint16_t acc_y = (data[2] << 8) | data[3];
        uint16_t acc_z = (data[4] << 8) | data[5];

        // Print readings
        printf("Acceleration (X: %hu, Y: %hu, Z: %hu) m/s^2\n", acc_x, acc_y, acc_z);

        // Sleep for 0.1 seconds
        tv.tv_sec = 0;
        tv.tv_usec = 100000;
        if (select(1, NULL, &tv, NULL, NULL) < 0) {
            perror("select failed");
            break; // Exit on interrupt
        }

        // Convert timeval to timespec for nanosleep
        ts = { .tv_sec = tv.tv_sec, .tv_nsec = tv.tv_usec * 1000 };

        // Wait for 0.1 seconds
        if (nanosleep(&ts, NULL) < 0) {
            perror("nanosleep failed");
            break; // Exit on interrupt
        }
    }

    // Close I2C device and release resources
    close(fd);
    return 0;
}

