#include <linux/i2c-dev.h>

#define TCS34725_ADDR 0x20 // Assuming the TCS34725 is at address 0x20
#define TCS34725_REG_RDSI 0x33 // Register to read raw data from sensor

int main() {
    int fd;
    uint8_t buf[6]; // Buffer to store 6 bytes of data from TCS34725
    int rdsi_data[3]; // Array to hold the RDSI data

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Check if the device is present
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) == -1) {
        perror("Failed to access I2C slave");
        close(fd);
        return EXIT_FAILURE;
    }

    // Function to read data from TCS34725
    void read_tcs34725() {
        int bytes_read;
        // Write to the register to start conversion
        if (ioctl(fd, I2C_WRITE, (char *) &TCS34725_REG_RDSI, 1) == -1) {
            perror("Failed to write to TCS34725");
            close(fd);
            return;
        }

        // Read 6 bytes of data
        bytes_read = read(fd, buf, 6);
        if (bytes_read != 6) {
            perror("Failed to read from TCS34725");
            close(fd);
            return;
        }

        // Convert the raw data to RDSI values
        rdsi_data[0] = (buf[0] << 8) | buf[1];
        rdsi_data[1] = (buf[2] << 8) | buf[3];
        rdsi_data[2] = (buf[4] << 8) | buf[5];

        // Print the RDSI values
        printf("RDSI: %d, %d, %d\n", rdsi_data[0], rdsi_data[1], rdsi_data[2]);
    }

    // Main loop
    while (1) {
        read_tcs34725();
        usleep(200000); // Sleep for 0.2 seconds
    }

    // Close the I2C device and release resources
    close(fd);
    return EXIT_SUCCESS;
}

