#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/videodev2.h>
#include <gst/gst.h>
#include <gst/video/gstvideomediaobject.h>
#include <gst/base/gstbasesink.h>
#include <gst/promise/gstpromise.h>

#define VIDEO_DEVICE "/dev/video0"
#define CAPTURE_IMAGE_FILE "capture.jpg"

int main() {
    // Initialize GStreamer for video capture
    GstElement *pipeline;
    GstBus *bus;
    GstPromise *promise;

    // Initialize libgpiod for releasing resources
    int fd = open("/dev/gpiomem", O_RDWR | O_SYNC);
    if (fd == -1) {
        perror("Failed to open /dev/gpiomem");
        return 1;
    }

    // Create GStreamer pipeline
    pipeline = gst_pipeline_new("video_capture_pipeline");
    if (!pipeline) {
        perror("Failed to create GStreamer pipeline");
        close(fd);
        return 1;
    }

    // Add elements to the pipeline
    GstElement *src = gst_element_factory_make("v4l2src", "video_source");
    if (!src) {
        perror("Failed to create v4l2src element");
        gst_object_unref(pipeline);
        close(fd);
        return 1;
    }

    GstElement *sink = gst_element_factory_make("gstbasesink", "sink");
    if (!sink) {
        perror("Failed to create sink element");
        gst_object_unref(src);
        gst_object_unref(pipeline);
        close(fd);
        return 1;
    }

    // Set properties for v4l2src
    if (gst_element_set_property(pipeline, src, "device", GSTRANGE("video_device"))) {
        perror("Failed to set v4l2src device property");
        gst_object_unref(src);
        gst_object_unref(sink);
        gst_object_unref(pipeline);
        close(fd);
        return 1;
    }
    gst_object_unref(GST_OBJECT(src));

    // Set sink pad
    if (gst_element_link(pipeline, src, sink)) {
        perror("Failed to link elements");
        gst_object_unref(src);
        gst_object_unref(sink);
        gst_object_unref(pipeline);
        close(fd);
        return 1;
    }
    gst_object_unref(GST_OBJECT(src));

    // Create a bus handler for promise
    bus = gst_pipeline_get_bus(GST_PIPELINE(pipeline));
    promise = gst_bus_add_watch(bus, bus_callback, NULL);
    gst_object_unref(bus);

    // Start the pipeline
    if (gst_element_set_state(pipeline, GST_STATE_PLAYING)) {
        perror("Failed to start the pipeline");
        gst_object_unref(promise);
        gst_object_unref(pipeline);
        close(fd);
        return 1;
    }

    // Wait for the promise to be fulfilled
    if (!gst_promise_wait(promise, GST_CLOCK_TIME_NONE, NULL)) {
        perror("Failed to wait for promise");
        gst_object_unref(promise);
        gst_object_unref(pipeline);
        close(fd);
        return 1;
    }

    // Capture image
    char buffer[4096];
    ssize_t bytes_read;
    while ((bytes_read = read(VIDEO_DEVICE, buffer, sizeof(buffer))) > 0) {
        // Save the captured image to a file
        FILE *file = fopen(CAPTURE_IMAGE_FILE, "wb");
        if (!file) {
            perror("Failed to open file for writing");
            break;
        }
        fwrite(buffer, 1, bytes_read, file);
        fclose(file);
    }

    // Handle error if no data was read
    if (bytes_read == 0) {
        perror("No data read from video device");
        return 1;
    }

    // Release resources
    gst_element_set_state(pipeline, GST_STATE_NULL);
    gst_object_unref(pipeline);
    close(fd);

    return 0;
}

// Callback function for bus messages
void bus_callback(GstBus *bus, GstMessage *msg, gpointer user_data) {
    if (GST_MESSAGE_TYPE(msg) == GST_MESSAGE_EOS) {
        g_print("End of Stream\n");
        gst_promise_cancel(promise);
        return;
    }
    g_print("Error: %s\n", GST_MESSAGE_ERRORDetails(msg));
    gst_object_unref(promise);
    gst_object_unref(pipeline);
    close(fd);
    exit(1);
}

