        perror("gpiod_init");
        return EXIT_FAILURE;
    }

    // Open GPIO pins
    struct gpiod_dir *trigger_dir = gpiod_open(TRIGGER_PIN, GPIOD_OUT_INIT_LOW);
    struct gpiod_dir *echo_dir = gpiod_open(ECHO_PIN, GPIOD_OUT_INIT_LOW);
    struct gpiod_dir *control_dir = gpiod_open(CONTROL_PIN, GPIOD_OUT_INIT_LOW);

    if (!trigger_dir || !echo_dir || !control_dir) {
        perror("gpiod_open");
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set trigger pin to output
    if (gpiod_direction_output(trigger_dir, 1) < 0) {
        perror("gpiod_direction_output (trigger)");
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set echo pin to input
    if (gpiod_direction_input(echo_dir) < 0) {
        perror("gpiod_direction_input (echo)");
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set control pin to output
    if (gpiod_direction_output(control_dir, 0) < 0) {
        perror("gpiod_direction_output (control)");
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Trigger the HC-SR04
        gpiod_write(trigger_dir, 1);
        sleep(0.1); // Wait for the trigger to settle

        // Set control pin high, then low to trigger the ultrasonic sensor
        gpiod_write(control_dir, 1);
        sleep(0.00001); // Minimal delay to ensure control pin is high
        gpiod_write(control_dir, 0);

        // Wait for echo pin to go high
        while (gpiod_read(echo_dir) == 0) {
            // No echo detected, give up after a timeout
            if (sleep(0.01) > 0.2) {
                break;
            }
        }

        // Measure the time until echo pin goes low again
        uint32_t echo_time = micros();

        // Wait for echo pin to go low
        while (gpiod_read(echo_dir) == 1) {
            if (sleep(0.01) > 0.2) {
                break;
            }
        }

        echo_time -= micros();

        // Calculate distance
        float distance = (echo_time / 58.0) * 0.034;

        printf("Distance: %.2f cm\n", distance);

        // Sleep for 0.2 seconds before next measurement
        sleep(200000);
    }

    // Clean up GPIO resources
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

