// Function to capture an image and save it to a file
void capture_image_and_save(const char *filename) {
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    int ret;

    // Initialize the format structure
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920; // Adjust width as needed
    fmt.fmt.pix.height = 1080; // Adjust height as needed
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;

    // Open the video device
    camera_fd = open(VIDEO_DEVICE, O_RDWR);
    if (camera_fd == -1) {
        perror("Failed to open video device");
        return;
    }

    // Request format
    ret = ioctl(camera_fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Failed to set format");
        close(camera_fd);
        return;
    }

    // Allocate buffer
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(camera_fd, VIDIOC_REQBUFS, &buf);
    if (ret < 0) {
        perror("Failed to request buffer");
        close(camera_fd);
        return;
    }

    // Map buffer memory
    ret = mmap(NULL, buf.buffer.size, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, 0);
    if (ret == MAP_FAILED) {
        perror("Failed to map buffer memory");
        close(camera_fd);
        return;
    }

    // Capture frame
    ret = read(camera_fd, buf.buffer.mapped, buf.buffer.size);
    if (ret < 0) {
        perror("Failed to capture frame");
        munmap(buf.buffer.mapped, buf.buffer.size);
        close(camera_fd);
        return;
    }

    // Save the captured frame to a file
    const char *data = buf.buffer.mapped;
    size_t len = ret;
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Failed to open file for writing");
        munmap(buf.buffer.mapped, buf.buffer.size);
        close(camera_fd);
        return;
    }
    fwrite(data, 1, len, fp);
    fclose(fp);

    // Unmap buffer memory
    munmap(buf.buffer.mapped, buf.buffer.size);

    // Release buffer
    ret = ioctl(camera_fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        perror("Failed to dequeue buffer");
        close(camera_fd);
        return;
    }
}

// Function to check if the camera is present
int check_camera_presence(void) {
    int fd = open("/dev/video0", O_RDONLY);
    if (fd == -1) {
