        uint16_t humidity = (data[0] << 8) | data[1];
        printf("Humidity: %hu%\n", humidity);

        // Sleep for 5 seconds
        usleep(5000000);

        // Close the I2C device before the next read to avoid resource leaks
        close(fd);
        fd = open("/dev/i2c-1", O_RDWR);
        if (fd == -1) {
            perror("Failed to reopen I2C device");
            return EXIT_FAILURE;
        }

        // Re-acquire the BME280 device
        if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) == -1) {
