    struct gpiod_dir *control_dir = gpiod_get_dir(gpiod_get_device(), CONTROL_PIN);
    struct gpiod_set_value *control_set = gpiod_get_set_value(control_dir);

    // Set trigger pin to output
    if (gpiod_set_value(trigger_set, GPIOD_OUTPUT) < 0) {
        perror("gpiod_set_value (trigger output)");
        gpiod_put_dir(trigger_dir, NULL);
        gpiod_put_dir(echo_dir, NULL);
        gpiod_put_dir(control_dir, NULL);
        gpiod_close();
        return EXIT_FAILURE;
    }

    // Set echo pin to input
    if (gpiod_set_value(echo_set, GPIOD_INPUT) < 0) {
        perror("gpiod_set_value (echo input)");
        gpiod_put_dir(trigger_dir, NULL);
        gpiod_put_dir(echo_dir, NULL);
        gpiod_put_dir(control_dir, NULL);
        gpiod_close();
        return EXIT_FAILURE;
    }

    // Set control pin to output
    if (gpiod_set_value(control_set, GPIOD_OUTPUT) < 0) {
        perror("gpiod_set_value (control output)");
        gpiod_put_dir(trigger_dir, NULL);
        gpiod_put_dir(echo_dir, NULL);
        gpiod_put_dir(control_dir, NULL);
        gpiod_close();
        return EXIT_FAILURE;
    }

