        unsigned long start = microsecond();
        while (gpiod_get_value(echo_set) == 0) {
            // Wait for echo pin to go high
            if (microsecond() - start > 200000) {
                // Timeout, failed reading
                printf("Failed to get echo signal\n");
                break;
            }
