    if (mqtt_client == NULL) {
        fprintf(stderr, "Failed to create MQTT client\n");
        return EXIT_FAILURE;
    }

    // Connect to MQTT broker
    if (mqtt_client_connect(mqtt_client, MQTT_BROKER, 1883, 0) < 0) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mqtt_client_last_error(mqtt_client));
        mqtt_client_disconnect(mqtt_client);
        mqtt_client_free(mqtt_client);
        return EXIT_FAILURE;
    }

    // Subscribe to the topic
    if (mqtt_client_subscribe(mqtt_client, MQTT_TOPIC, 1) < 0) {
        fprintf(stderr, "Failed to subscribe to topic: %s\n", mqtt_client_last_error(mqtt_client));
        mqtt_client_disconnect(mqtt_client);
        mqtt_client_free(mqtt_client);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Check if the device is present
        check_device_presence();

        // Read sensor value
        if (read_sensor_value(GPIO_PIN)) {
            // Publish the sensor reading
            publish_mqtt_message("Sensor Value: ");
            // Sleep for a short period to avoid rapid publishing
            usleep(100000);
        } else {
            // Sensor reading failed, possibly due to device absence
            printf("Sensor reading failed. Device may be absent.\n");
            break; // Exit the loop
        }

