// Function to setup ADS1115
void setup_ads1115() {
    struct ads1115_config ads1115_config;
    ads1115_config.gain = ADS1115_GAIN_1X;
    ads1115_config.reference = ADS1115_REF_VCC;
    ads1115_config.mode = ADS1115_MODE_12B;

    if (libads1115_init(&ads1115_config) != ADS1115_OK) {
        perror("Failed to initialize ADS1115");
        exit(EXIT_FAILURE);
    }

    // Set GPIO pin as input
    if (gpiod_direction_input(GPIO_NUM_AD_IN0) != 0) {
        perror("Failed to configure GPIO pin as input");
        libads1115_deinit();
        exit(EXIT_FAILURE);
    }
}

// Function to read ADS1115 value
void read_ads1115_value(int channel, float *value) {
    if (libads1115_start_conversion(ADS1115_CHANNEL_0, channel) != ADS1115_OK) {
        perror("Failed to start conversion");
        return;
    }

    if (libads1115_end_conversion_and_read(ADS1115_CHANNEL_0, value) != ADS1115_OK) {
        perror("Failed to read conversion result");
        libads1115_stop_conversion();
        return;
    }
}

