    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Open GPIO controller
    struct gpiod_device *gpiodev;
    if ((gpiodev = gpiod_get_device(GPIO_NUM)) == NULL) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO pin
    struct gpiod_pin *pin;
    if ((pin = gpiod_pin_new(gpiodev, GPIO_NUM)) == NULL) {
        fprintf(stderr, "Failed to open GPIO pin %d: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
        gpiod_pin_free(pin);
        gpiod_device_put(gpiodev);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set up pin direction and output
    if (gpiod_pin_direction(pin, GPIO_OUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d direction: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
        gpiod_pin_free(pin);
        gpiod_device_put(gpiodev);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Loop indefinitely, updating the pin state every 0.1 seconds
    while (1) {
        // Toggle the pin state
        if (gpiod_pin_write(pin, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO pin %d to high: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
            break; // Exit loop on failure
        }
        if (gpiod_pin_write(pin, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO pin %d to low: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
            break; // Exit loop on failure
        }

        // Sleep for 0.1 seconds
        usleep(100000);

        // Report the current state
        if (gpiod_pin_read(pin) == 1) {
            printf("GPIO pin %d is HIGH\n", GPIO_NUM);
        } else {
            printf("GPIO pin %d is LOW\n", GPIO_NUM);
        }
    }

    // Cleanup resources
    gpiod_pin_free(pin);
    gpiod_device_put(gpiodev);
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

#include <stdio.h>
