#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>

#define SERIAL_PORT "/dev/ttyAMA0" // Adjust according to your Raspberry Pi's serial port

int main() {
    // Open the serial port
    int fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Get the current terminal settings
    struct termios options;
    tcgetattr(fd, &options);

    // Set the options for non-blocking, 8N1, no hardware flow control
    options.c_cflag = (options.c_cflag & ~CSIZE) | CS8;
    options.c_cflag |= CLOCAL; // Makes the terminal line local
    options.c_cflag &= ~PARENB; // Disable parity
    options.c_cflag &= ~CSTOPB; // One stop bit
    options.c_lflag &= ~(ICANON | ECHO); // No canonical processing, no echo

    // Set the new options
    tcsetattr(fd, TCSANOW, &options);

    // Loop indefinitely until interrupted
    while (1) {
        // Read data from the serial port
        char buffer[256];
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            perror("read");
            break; // Exit on error
        }

        // Print the received data
        printf("Received: %s\n", buffer);

        // Release resources on interrupt (SIGINT)
        if (bytes_read == SIGINT) {
            // Clean up and close the serial port
            tcsetattr(fd, TCSAFLUSH, &options);
            close(fd);
            return EXIT_SUCCESS;
        }
    }

    // Clean up and close the serial port
    tcsetattr(fd, TCSAFLUSH, &options);
    close(fd);

    return EXIT_SUCCESS;
}

