    uint16_t temperature = (data[0] << 8) | data[1];
    uint16_t pressure = (data[2] << 8) | data[3];

    pressure = (pressure * 16384.0) / (pow(2, temperature));

    return pressure;
}

// BMP280 temperature calculation function
float bmp280_read_temperature(uint8_t data[2]) {
    uint16_t temperature = (data[0] << 8) | data[1];
    return (temperature * 0.5) - 25.0; // Convert to degrees Celsius
}

