#define MQTT_BROKER "mqtt.eclipse.org" // MQTT broker URL
#define MQTT_TOPIC "raspberry_pi/gpio_state" // Topic to publish to

// GPIO pin number to read from
#define GPIO_PIN 17

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret != 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpiod_errstr(ret));
        return EXIT_FAILURE;
    }

    // Open the GPIO pin
    struct gpiod_pin_desc *pin_desc = gpiod_get_pin_desc_by_number(GPIO_PIN);
    if (!pin_desc) {
        fprintf(stderr, "Failed to get GPIO pin descriptor: %s\n", gpiod_errstr(gpiod_error()));
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Initialize paho MQTT client
    MQTTClient *client = mqtt_client_new();
    if (!client) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", mqtt_client_errstr());
        gpiod_pin_desc_free(pin_desc);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Connect to MQTT broker
    if (mqtt_client_connect(client, MQTT_BROKER, 1883, 0) != MQTT_CONNECT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mqtt_client_errstr());
        mqtt_client_free(client);
        gpiod_pin_desc_free(pin_desc);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Subscribe to the topic
    if (mqtt_client_subscribe(client, MQTT_TOPIC, 0) != MQTT_SUBSCRIBE_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to topic: %s\n", mqtt_client_errstr());
        mqtt_client_disconnect(client);
        mqtt_client_free(client);
        gpiod_pin_desc_free(pin_desc);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Main loop to read and publish GPIO state
    while (1) {
        // Read GPIO pin state
        int state = gpiod_get_value(pin_desc);

        // Publish the state to MQTT topic
        char msg[20];
        sprintf(msg, "GPIO %d: %d", GPIO_PIN, state);
        if (mqtt_client_publish(client, MQTT_TOPIC, msg, strlen(msg), 0) != MQTT_PUBLISH_SUCCESS) {
            fprintf(stderr, "Failed to publish message: %s\n", mqtt_client_errstr());
            break; // Exit loop on publish failure
        }
    }

    // Clean up
    mqtt_client_disconnect(client);
    mqtt_client_free(client);
    gpiod_pin_desc_free(pin_desc);
    gpiod_exit();

    return EXIT_SUCCESS;
}

