#define VIDEO_DEVICE "/dev/video0" // Assuming the camera is connected to /dev/video0

// Function prototypes
void capture_image_and_save(const char *filename);
int check_camera_presence(void);

int main(void) {
    int camera_fd = -1;
    int repeat = 1;
    while (repeat) {
        // Check if the camera is present
        if (check_camera_presence() == 0) {
            printf("Camera not found. Exiting...\n");
            return EXIT_FAILURE;
        }

        // Open the camera device
        camera_fd = open(VIDEO_DEVICE, O_RDWR);
        if (camera_fd == -1) {
            perror("Failed to open camera device");
            return EXIT_FAILURE;
        }

        // Capture and save the image
        capture_image_and_save("image.jpg");

        // Close the camera device after capturing
        close(camera_fd);

        // Sleep for 1 second
        sleep(1);
    }

    // Release the camera hardware
    gpiod_free_all();

    return EXIT_SUCCESS;
}

// Function to capture an image and save it to a file
void capture_image_and_save(const char *filename) {
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    int ret;

    // Initialize the format structure
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920; // Adjust width as per your camera's capability
    fmt.fmt.pix.height = 1080; // Adjust height as per your camera's capability
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;

    // Open the buffer memory
    ret = ioctl(camera_fd, VIDIOC_REQBUFS, &fmt);
    if (ret < 0) {
        perror("VIDIOC_REQBUFS");
        return;
    }

    // Allocate and fill buffer
    ret = ioctl(camera_fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("VIDIOC_QBUF");
        return;
    }

    // Capture the image
    ret = read(camera_fd, buf.data, buf.memory.size);
    if (ret < 0) {
        perror("Read error");
        return;
    }

    // Save the image to a file
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(buf.data, 1, ret, file);
    fclose(file);

    // Deallocate the buffer
    ret = ioctl(camera_fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        perror("VIDIOC_DQBUF");
        return;
    }
}

// Function to check if the camera is present
int check_camera_presence(void) {
    int fd = open(VIDEO_DEVICE, O_RDONLY);
    if (fd == -1) {
        if (errno == ENXIO) {
            // Camera not found, return 0
            return 0;
        } else {
            perror("Failed to open camera device for read");
            return EXIT_FAILURE;
        }
    }
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/videodev2.h>
#include <sys/ioctl.h>
#include <errno.h>

#define VIDEO_DEVICE "/dev/video0" // Assuming the camera is connected to /dev/video0

int main() {
    int fd = -1;
    int ret;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers reqbuf;
    unsigned char *buffer;
    ssize_t bytes_read;
    const char *filename = "output.jpg";

    // Open the video device
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    // Check if the device supports streaming
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request format and buffer information
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920; // Desired width
    fmt.fmt.pix.height = 1080; // Desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // Image format

    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbuf.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &reqbuf);
    if (ret < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate and map the buffer memory
    buffer = mmap(NULL, reqbuf.count * reqbuf.memory_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, reqbuf.memory_offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return EXIT_FAILURE;
    }

    // Capture the image
    ret = ioctl(fd, VIDIOC_STREAMON, &fmt);
    if (ret < 0) {
        perror("VIDIOC_STREAMON");
        munmap(buffer, reqbuf.count * reqbuf.memory_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Wait for the image to be captured (timeout after 5 seconds)
    struct timespec timeout = {5, 0};
    ret = nanosleep(&timeout, NULL);
    if (ret == -1) {
        perror("nanosleep");
        close(fd);
        munmap(buffer, reqbuf.count * reqbuf.memory_size);
        return EXIT_FAILURE;
    }

    // Capture the image
    ret = ioctl(fd, VIDIOC_GRBFMT, &fmt);
    if (ret < 0) {
        perror("VIDIOC_GRBFMT");
        munmap(buffer, reqbuf.count * reqbuf.memory_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Read the captured image data
    bytes_read = read(fd, buffer, reqbuf.count * reqbuf.memory_size);
    if (bytes_read != reqbuf.count * reqbuf.memory_size) {
        perror("Read error");
        munmap(buffer, reqbuf.count * reqbuf.memory_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Save the image to a file
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("fopen");
        munmap(buffer, reqbuf.count * reqbuf.memory_size);
        close(fd);
        return EXIT_FAILURE;
    }

    fwrite(buffer, reqbuf.count * reqbuf.memory_size, 1, file);
    fclose(file);

    // Release the buffer memory
    munmap(buffer, reqbuf.count * reqbuf.memory_size);

    // Close the video device
    ret = ioctl(fd, VIDIOC_STREAMOFF, &fmt);
    if (ret < 0) {
        perror("VIDIOC_STREAMOFF");
        close(fd);
        return EXIT_FAILURE;
    }

    close(fd);

    return EXIT_SUCCESS;
}

