    if (fd_gpio02 < 0 || fd_gpio03 < 0) {
        fprintf(stderr, "Error opening GPIOs: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_close(chip, fd_gpio02);
        gpiod_close(chip, fd_gpio03);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Function to toggle GPIO state and print the current state
    void toggle_and_print(int fd) {
        int state;
        // Toggle the GPIO state
