    // Main loop
    while (1) {
        toggle_and_print(fd_gpio02);
        toggle_and_print(fd_gpio03);

        // Sleep for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup on interrupt (e.g., Ctrl+C)
    if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
        fprintf(stderr, "Error ignoring SIGINT: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Handle interrupt by cleaning up and exiting
    signal(SIGINT, SIG_DFL); // Restore default SIGINT handler
    gpiod_close(chip, fd_gpio02);
    gpiod_close(chip, fd_gpio03);
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

