        }

        value = gpiod_get_value(gpio);
        if (!value) {
            fprintf(stderr, "Error getting value for GPIO %d: %s\n", gpio, gpiod_errstr(gpiod_get_error()));
            gpiod_put_direction(direction, GPIOD_DIR_INPUT); // Reset direction before continuing
            continue;
        }

        // Set GPIO to output
        gpiod_put_direction(direction, GPIOD_DIR_OUT);

        // Set GPIO high
        gpiod_set_value(value, 1);

        // Wait for 0.5 seconds
        sleep(0.5);

        // Set GPIO low
        gpiod_set_value(value, 0);

        // Release resources
        gpiod_put_value(value, 0);
        gpiod_put_direction(direction, GPIOD_DIR_INPUT);
        gpiod_put_direction(direction, GPIOD_DIR_NONE);
        gpiod_put_value(value, NULL);

        printf("Set GPIO %d to %s\n", gpio, (value->value == 1) ? "high" : "low");
    }

