#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <string.h>

#define SERIAL_PORT "/dev/ttyAMA0" // Adjust according to your Raspberry Pi's serial port

int main() {
    int fd; // File descriptor for the serial port
    struct termios options; // Option settings for the serial port
    char buffer[256]; // Buffer for reading from the serial port

    // Open the serial port
    fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Get the current settings
    if (tcgetattr(fd, &options) == -1) {
        perror("tcgetattr");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the options: no hardware flow control, 8N1, no parity, one stop bit
    options.c_cflag = (options.c_cflag & ~CSIZE) | CS8;
    options.c_cflag |= CLOCAL; // Make it local (ignore modem controls)
    options.c_cflag &= ~PARENB; // No parity
    options.c_cflag &= ~CSTOPB; // One stop bit

    // Enable software flow control (RTS/CTS)
    options.c_iflag &= ~(IXON | IXOFF | IXANY);

    // Set baud rate to 115200 (adjust as needed)
    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);

    // Set the new options
    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        perror("tcsetattr");
        close(fd);
        return EXIT_FAILURE;
    }

    // Loop indefinitely, reading and printing data
    while (1) {
        // Read data from the serial port
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            perror("read");
            break; // Exit loop on error
        }

        // Print the received data
        printf("Received: %s\n", buffer);
    }

    // Close the serial port and restore original settings
    if (tcsetattr(fd, TCSAFLUSH, &options) == -1) {
        perror("tcsetattr");
        close(fd);
        return EXIT_FAILURE;
    }

    close(fd);

    return EXIT_SUCCESS;
}

