        mqtt_client_delete(mqtt_client);
    }
}

void callback(paho::Client *client, paho::Conn *conn, uint8_t flags, void *user) {
    if (flags & MQTT_CONNECT) {
        printf("Connected to MQTT broker\n");
    } else if (flags & MQTT_DISCONNECT) {
        printf("Disconnected from MQTT broker\n");
    } else if (flags & MQTT_SUBSCRIBE) {
        printf("Subscribed to topic: %s\n", mqtt_last_topic(client));
    } else if (flags & MQTT_PUBLISH) {
        printf("Published message: %.*s\n", (int)mqtt_last.payloadlen, mqtt_last.payload);
    }
}

