#define VIDEO_DEVICE "/dev/video0" // Assuming the camera is connected to /dev/video0

int main() {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_framebuffer header;
    unsigned char *buffer;
    ssize_t bytes_read;
    const char *filename = "output.jpg";

    // Open the video device
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    // Check if the device supports video capture
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Query format capabilities
    if (ioctl(fd, VIDIOC_G_FMT, &fmt) == -1) {
        perror("VIDIOC_G_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate buffer for one frame
    buffer = malloc(fmt.frame_size);
    if (!buffer) {
        perror("malloc failed");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the format
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Prepare the framebuffer header
    header.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    header.memory = V4L2_MEMORY_MMAP;

    // Map the buffer memory
    if (ioctl(fd, VIDIOC_REQBUFS, &header) == -1) {
        perror("VIDIOC_REQBUFS");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffer memory
    if (ioctl(fd, VIDIOC_MMAP, &header) == -1) {
        perror("VIDIOC_MMAP");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (ioctl(fd, VIDIOC_STREAMON, &header) == -1) {
        perror("VIDIOC_STREAMON");
        munmap(buffer, fmt.frame_size);
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Wait for a frame to be captured
    bytes_read = read(fd, buffer, fmt.frame_size);
    if (bytes_read == -1) {
        perror("Read error");
        munmap(buffer, fmt.frame_size);
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Save the captured image to a file
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        munmap(buffer, fmt.frame_size);
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    fwrite(buffer, 1, bytes_read, file);
    fclose(file);

    // Unmap the buffer memory
    munmap(buffer, fmt.frame_size);
    free(buffer);

    // Close the video device
    close(fd);

    return EXIT_SUCCESS;
}

