#define PCF8574_ADDR 0x27  // Address of the PCF8574 I2C device

// Define the PCF8574 register addresses
#define REG_DATA        0x00
#define REG_CONTROL     0x01

// Function prototypes
void display_pcf8574_values();
void cleanup();

int main() {
    int fd;
    struct i2c_msg msg[2];

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C message structures
    msg[0].addr = PCF8574_ADDR;
    msg[0].len = sizeof(uint8_t);
    msg[0].buf = &REG_DATA;

    msg[1].addr = PCF8574_ADDR;
    msg[1].len = sizeof(uint8_t);
    msg[1].buf = &REG_CONTROL;

    // Main loop
    while (1) {
        // Read data register
        if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) == -1) {
            perror("Error: ioctl(I2C_SLAVE)");
            exit(EXIT_FAILURE);
        }
        if (read(fd, &REG_DATA, sizeof(uint8_t)) != sizeof(uint8_t)) {
            perror("Error reading data register");
            exit(EXIT_FAILURE);
        }

        // Read control register
        if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) == -1) {
            perror("Error: ioctl(I2C_SLAVE)");
            exit(EXIT_FAILURE);
        }
        if (read(fd, &REG_CONTROL, sizeof(uint8_t)) != sizeof(uint8_t)) {
            perror("Error reading control register");
            exit(EXIT_FAILURE);
        }

        // Display values
        display_pcf8574_values();

        // Sleep for 0.5 seconds
        usleep(500000);

        // Cleanup on interrupt (Ctrl+C)
        if (signal(SIGINT, cleanup) == SIG_ERR) {
            perror("Error setting signal handler");
            exit(EXIT_FAILURE);
        }
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

// Function to display PCF8574 values
void display_pcf8574_values() {
    uint8_t data = REG_DATA;
    uint8_t control = REG_CONTROL;

    printf("PCF8574 DATA register value: 0x%X\n", data);
    printf("PCF8574 CONTROL register value: 0x%X\n", control);

    // Ensure values are within the documented range
    if (data > 0xFF || data < 0x00) {
        printf("DATA value out of range (0x%X)\n", data);
    }
    if (control > 0xFF || control < 0x00) {
        printf("CONTROL value out of range (0x%X)\n", control);
    }
}

// Function to release resources on interrupt (Ctrl+C)
void cleanup() {
    close(fd);
    printf("PCF8574 I2C device closed.\n");
}

