// Function to initialize pigpio library
void setup_pigpio() {
    if (gpiod_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpiod_errstr());
        exit(EXIT_FAILURE);
    }
}

// Function to apply PWM settings to specified GPIO pins
void apply_pwm_settings(int gpio, int duty_cycle) {
    if (gpiowrite(gpio, PI_HIGH, PI_LOW, duty_cycle / 100.0) == -1) {
        fprintf(stderr, "Failed to set PWM on GPIO %d: %s\n", gpio, gpiod_errstr());
        exit(EXIT_FAILURE);
    }
    printf("PWM set to %d%% duty cycle on GPIO %d\n", duty_cycle, gpio);
}

// Function to clean up resources after pigpio library usage
void cleanup_pigpio() {
    gpiod_cleanup();
}

// Main loop function
void main_loop() {
    // Define GPIO pins and duty cycles
    const int gpios[] = {8, 9, 11, 18}; // BCM GPIO numbers
    const int duty_cycles[] = {50, 75, 25, 100}; // Duty cycles in percent

    // Iterate over GPIO pins and duty cycles
    for (int i = 0; i < sizeof(gpios) / sizeof(gpios[0]); ++i) {
        apply_pwm_settings(gpios[i], duty_cycles[i]);
        sleep(1); // Wait 1 second before changing next setting
    }
}

#include <stdio.h>
