#include <gst/video/gstvideomediaobject.h>
#include <gst/video/gstvideosink.h>
#include <gst/promise.h>

#define VIDEO_DEVICE "/dev/video0"
#define CAPTURE_IMAGE_INTERVAL 0.1

#define VIDEO_CAPS "video/x-raw,format=UYVY,width=640,height=480"

GstBus *bus;
GstElement *pipeline;
GstPromise *promise;

int main() {
    int fd;
    char filename[256];
    char *error_message;
    ssize_t bytes_read;
    struct timeval start, end;
    double interval;

    // Initialize GStreamer
    bus = gst_init(NULL, NULL);
    if (!bus) {
        fprintf(stderr, "Failed to initialize GStreamer: %s\n", gst_get_error_message(bus));
        return EXIT_FAILURE;
    }

    // Create the pipeline
    pipeline = gst_pipeline_new("camera_capture_pipeline");
    if (!pipeline) {
        fprintf(stderr, "Failed to create pipeline: %s\n", gst_get_error_message(bus));
        gst_bus_unref(bus);
        return EXIT_FAILURE;
    }

    // Create a video sink
    GstElement *videosink = gst_element_factory_make("gstvideosink", "videosink");
    if (!videosink) {
        fprintf(stderr, "Failed to create video sink: %s\n", gst_get_error_message(bus));
        gst_object_unref(pipeline);
        gst_bus_unref(bus);
        return EXIT_FAILURE;
    }

    // Add the video sink to the pipeline
    gst_bin_add_many(NULL, pipeline, videosink, NULL);

    // Set the video caps
    GstCaps *caps = gst_caps_new_simple("video/x-raw", 
                                         "format", G_TYPE_STRING, "UYVY", 
                                         "width", G_TYPE_INT, 640,
                                         "height", G_TYPE_INT, 480,
                                         NULL);
    if (!caps) {
        fprintf(stderr, "Failed to create video caps: %s\n", gst_get_error_message(bus));
        gst_object_unref(pipeline);
        gst_element_set_state(videosink, GST_STATE_NULL);
        gst_object_unref(videosink);
        gst_bus_unref(bus);
        return EXIT_FAILURE;
    }

    // Set the caps on the video sink
    gst_element_set_property(pipeline, videosink, GST_OBJECT_PROPERTY_CAPS, caps);
    gst_caps_free(caps);

    // Promise for cancelling the pipeline
    promise = gst_promise_new();
    if (!promise) {
        fprintf(stderr, "Failed to create promise: %s\n", gst_get_error_message(bus));
        gst_object_unref(pipeline);
        gst_element_set_state(videosink, GST_STATE_NULL);
        gst_object_unref(videosink);
        gst_bus_unref(bus);
        return EXIT_FAILURE;
    }

    // Open the video device
    fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        error_message = "Failed to open video device: ";
        if (errno == ENXIO) {
            error_message += "Device not present";
        } else if (errno == EBUSY) {
            error_message += "Device in use";
        } else {
            error_message += "Unknown error: " + strerror(errno);
        }
        fprintf(stderr, "%s\n", error_message);
        gst_object_unref(pipeline);
        gst_element_set_state(videosink, GST_STATE_NULL);
        gst_promise_unref(promise);
        gst_bus_unref(bus);
        return EXIT_FAILURE;
    }

    // Set non-blocking mode
    if (fcntl(fd, F_SETFL, O_NONBLOCK) == -1) {
        fprintf(stderr, "Failed to set non-blocking mode: %s\n", strerror(errno));
        close(fd);
        error_message = "Failed to set non-blocking mode: ";
        if (errno == EAGAIN) {
            error_message += "Operation would block";
        } else {
            error_message += "Unknown error: " + strerror(errno);
        }
        fprintf(stderr, "%s\n", error_message);
        gst_object_unref(pipeline);
        gst_element_set_state(videosink, GST_STATE_NULL);
        gst_promise_unref(promise);
        gst_bus_unref(bus);
        return EXIT_FAILURE;
    }

    // Start the capture loop
    interval = 1.0 / CAPTURE_IMAGE_INTERVAL;
    gettimeofday(&start, NULL);

    while (1) {
        // Capture image
        gst_element_set_state(pipeline, GST_STATE_PAUSED);
        if (gst_element_query_state(pipeline) != GST_STATE_PAUSED) {
            fprintf(stderr, "Failed to pause: %s\n", gst_get_error_message(bus));
            break;
        }

        if (gst_promise_poll(promise, GST_CLOCK_TIME_NONE, interval * 1000000) > 0) {
            gst_element_set_state(pipeline, GST_STATE_NULL);
            gst_promise_unref(promise);

            // Capture the image
            bytes_read = read(fd, (void *)&image_data, 640 * 480 * 2);
            if (bytes_read < 640 * 480 * 2) {
                fprintf(stderr, "Failed to read image: %zd bytes read, expected %zd\n", bytes_read, 640 * 480 * 2);
                break;
            }

            // Save the image to a file
            snprintf(filename, sizeof(filename), "image_capture_%ld.jpg", (long)time(NULL));
            FILE *file = fopen(filename, "wb");
            if (!file) {
                fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
                continue; // Continue if file open fails, might be due to disk full
            }
            fwrite((void *)image_data, 1, bytes_read, file);
            fclose(file);

            // Release resources
            close(fd);
            fd = -1;
        } else {
            // Device did not respond, release resources and exit
            gst_element_set_state(pipeline, GST_STATE_NULL);
            gst_promise_unref(promise);
            break;
        }
    }

    // Clean up
    gst_element_set_state(pipeline, GST_STATE_NULL);
    gst_object_unref(pipeline);
    gst_promise_unref(promise);
    gst_bus_unref(bus);

    return EXIT_SUCCESS;
}

