#define PCF8574_ADDR 0x27  // I2C address of the PCF8574

// Function prototypes
void error(const char *msg);
void release_resources();

int main() {
    int fd;
    uint8_t data[8];  // Data buffer for reading from PCF8574

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        error("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Check if device is writable
    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) == -1) {
        error("Failed to acquire I2C slave");
        close(fd);
        return EXIT_FAILURE;
    }

    // Attempt to read from the PCF8574
    if (read(fd, data, 8) != 8) {
        error("Failed to read from PCF8574");
        close(fd);
        return EXIT_FAILURE;
    }

    // Display the read data
    for (int i = 0; i < 8; i++) {
        printf("PCF8574 register %d: 0x%02X\n", i, data[i]);
    }

    // Release resources
    release_resources();

    return EXIT_SUCCESS;
}

// Utility function to print error message and exit
void error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

// Function to release resources (close I2C device)
void release_resources() {
    close(fd);
}

