#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

int main() {
    // Initialize libgpiod
    int ret = gpiod_init();
    if (ret != 0) {
        fprintf(stderr, "gpiod_init failed: %s\n", gpiod_errstr(ret));
        return EXIT_FAILURE;
    }

    // Open GPIO pins
    struct gpiod_dir *trigger_dir = gpiod_get_direction(TRIGGER_PIN);
    struct gpiod_dir *echo_dir = gpiod_get_direction(ECHO_PIN);

    if (trigger_dir == NULL || echo_dir == NULL) {
        fprintf(stderr, "Failed to open GPIO pins: %s\n", gpiod_errstr(gpiod_get_last_error()));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set trigger pin to output
    ret = gpiod_set_value(trigger_dir, GPIOD_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set trigger pin to output: %s\n", gpiod_errstr(ret));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set echo pin to input
    ret = gpiod_set_value(echo_dir, GPIOD_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set echo pin to input: %s\n", gpiod_errstr(ret));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Function to trigger the HC-SR04 and read the echo pulse
    void measure_distance() {
        // Trigger the ultrasonic sensor
        gpiod_set_value(trigger_dir, 1);
        usleep(2); // Wait for the trigger pulse to settle

        // Start a timer to measure the echo pulse width
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        // Read the echo pin
        while (gpiod_get_value(echo_dir) == 0) {
            usleep(10); // Polling with a short delay
        }

        // Stop the timer
        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate the distance
        uint64_t duration = (uint64_t)(end.tv_sec * 1000000 + end.tv_nsec) - (uint64_t)(start.tv_sec * 1000000 + start.tv_nsec);
        float distance = (duration / 58.0) * 34300.0; // Assuming speed of sound is approximately 34300 m/s

        printf("Distance: %.2f cm\n", distance / 100.0);
    }

    // Attempt to measure distance
    measure_distance();

    // Cleanup GPIO resources
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

