#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_DEVICE_PATH "/dev/i2c-1" // Adjust according to your Raspberry Pi's I2C bus

#define MPU6050_ADDRESS 0x68 // Default I2C address for MPU6050

#define REG_ACCEL_XOUT_H 0x3B
#define REG_ACCEL_XOUT_L 0x3C
#define REG_ACCEL_YOUT_H 0x3D
#define REG_ACCEL_YOUT_L 0x3E
#define REG_ACCEL_ZOUT_H 0x3F
#define REG_ACCEL_ZOUT_L 0x40
#define REG_GYRO_XOUT_H 0x43
#define REG_GYRO_XOUT_L 0x44
#define REG_GYRO_YOUT_H 0x45
#define REG_GYRO_YOUT_L 0x46
#define REG_GYRO_ZOUT_H 0x47
#define REG_GYRO_ZOUT_L 0x48

#define MPU6050_ACCEL_DATA ((uint16_t)(REG_ACCEL_XOUT_H << 8) | REG_ACCEL_XOUT_L)
#define MPU6050_GYRO_DATA ((uint16_t)(REG_GYRO_XOUT_H << 8) | REG_GYRO_XOUT_L)

// Function prototypes
int i2c_open_device(const char *device_path);
void i2c_close_device(int fd);
int i2c_write(int fd, uint8_t slave_addr, uint8_t reg, uint8_t *data, size_t len);
int i2c_read(int fd, uint8_t slave_addr, uint8_t reg, uint8_t *data, size_t len);

int main() {
    int fd;
    int ret;
    uint8_t buf[6]; // Buffer for reading 3-axis accelerometer and gyroscope data

    // Attempt to open the I2C device
    fd = i2c_open_device(I2C_DEVICE_PATH);
    if (fd == -1) {
        perror("i2c_open_device");
        return EXIT_FAILURE;
    }

    // Initialize variables
    uint16_t accel_data = 0;
    uint16_t gyro_data = 0;

    // Main loop
    while (1) {
        // Read accelerometer data
        ret = i2c_write(fd, MPU6050_ADDRESS, REG_ACCEL_XOUT_H, &buf[0], 1);
        if (ret < 0) {
            perror("i2c_write (accelerometer)");
            break; // Exit on error
        }
        ret = i2c_read(fd, MPU6050_ADDRESS, REG_ACCEL_XOUT_L, &buf[0], 1);
        if (ret < 0) {
            perror("i2c_read (accelerometer low)");
            break; // Exit on error
        }
        accel_data = (buf[0] << 8) | buf[1]; // Combine high and low bytes

        // Read gyroscope data
        ret = i2c_write(fd, MPU6050_ADDRESS, REG_GYRO_XOUT_H, &buf[0], 1);
        if (ret < 0) {
            perror("i2c_write (gyroscope)");
            break; // Exit on error
        }
        ret = i2c_read(fd, MPU6050_ADDRESS, REG_GYRO_XOUT_L, &buf[0], 1);
        if (ret < 0) {
            perror("i2c_read (gyroscope low)");
            break; // Exit on error
        }
        gyro_data = (buf[0] << 8) | buf[1]; // Combine high and low bytes

        // Print data
        printf("Acceleration (x: %hu, y: %hu, z: %hu) m/s^2\n", accel_data >> 8, accel_data & 0xFF, 0);
        printf("Gyration (x: %hu, y: %hu, z: %hu) degrees/s\n", gyro_data >> 8, gyro_data & 0xFF, 0);

        // Sleep for 0.1 seconds
        usleep(100000);

        // Check for interrupt signal (SIGINT)
        if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
            perror("signal(SIGINT, SIG_IGN)");
            break; // Exit on error
        }
    }

    // Close the I2C device and release resources
    i2c_close_device(fd);

    // Exit with success
    return EXIT_SUCCESS;
}

// Function to open the I2C device
int i2c_open_device(const char *device_path) {
    int fd;
    struct stat st;

    if (stat(device_path, &st) != 0) {
        perror("stat");
        return -1;
    }

    if ((fd = open(device_path, O_RDWR)) < 0) {
        perror("open");
        return -1;
    }

    return fd;
}

// Function to close the I2C device
void i2c_close_device(int fd) {
    close(fd);
}

// Function to write data to the I2C device
int i2c_write(int fd, uint8_t slave_addr, uint8_t reg, uint8_t *data, size_t len) {
    int ret = write(fd, &slave_addr, sizeof(uint8_t));
    if (ret != sizeof(uint8_t)) {
        return ret;
    }

    ret = write(fd, &reg, sizeof(uint8_t));
    if (ret != sizeof(uint8_t)) {
        return ret;
    }

    ret = write(fd, data, len);
    if (ret != len) {
        return ret;
    }

    return len;
}

// Function to read data from the I2C device
int i2c_read(int fd, uint8_t slave_addr, uint8_t reg, uint8_t *data, size_t len) {
    int ret = write(fd, &slave_addr, sizeof(uint8_t));
    if (ret != sizeof(uint8_t)) {
        return ret;
    }

    ret = write(fd, &reg, sizeof(uint8_t));
    if (ret != sizeof(uint8_t)) {
        return ret;
    }

    ret = read(fd, data, len);
    if (ret != len) {
        return ret;
    }

    return ret;
}

