#define VIDEO_DEVICE "/dev/video0" // Assuming the camera is connected to /dev/video0

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers reqbuf;
    unsigned char *buffer;
    ssize_t num_bytes_read;
    int ret;

    // Open the video device
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open video device");
        return 1; // Exit with error if device is absent
    }

    // Get video device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return 1; // Exit with error if query fails
    }

    // Check if the device supports video capture
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1; // Exit with error if capture not supported
    }

    // Request buffers for capturing
    reqbuf.count = 1;
    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_REQBUFS, &reqbuf) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return 1; // Exit with error if buffer request fails
    }

    // Allocate buffer for image data
    buffer = (unsigned char *)malloc(cap.cap.b.width * cap.cap.b.height * 2); // Assuming YUV 4:2:0 format
    if (!buffer) {
        perror("Memory allocation failed");
        close(fd);
        return 1; // Exit with error if memory allocation fails
    }

    // Set video format
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = cap.cap.b.width;
    fmt.fmt.pix.height = cap.cap.b.height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // Assuming YUYV format
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        free(buffer); // Release buffer
        close(fd);
        return 1; // Exit with error if format set fails
    }

    // Start capturing
    if (ioctl(fd, VIDIOC_STREAMON, 0) < 0) {
        perror("VIDIOC_STREAMON");
        free(buffer); // Release buffer
        close(fd);
        return 1; // Exit with error if stream start fails
    }

    // Capture the image
    ret = read(fd, buffer, cap.cap.b.width * cap.cap.b.height * 2); // Capture the image data
    if (ret < 0) {
        perror("Read error");
        free(buffer); // Release buffer
        close(fd);
        return 1; // Exit with error if read fails
    }

    // Save the captured image to a file
    FILE *file = fopen("capture.jpg", "wb");
    if (!file) {
        perror("Failed to open file for writing");
        free(buffer); // Release buffer
        close(fd);
        return 1; // Exit with error if file open fails
    }

    fwrite(buffer, 1, ret, file); // Write the captured image to the file
    fclose(file);

    // Release the buffer
    free(buffer);

    // Stop capturing and release the device
    if (ioctl(fd, VIDIOC_STREAMOFF, 0) < 0) {
        perror("VIDIOC_STREAMOFF");
        close(fd);
        return 1; // Exit with error if stream stop fails
    }
    close(fd);

    return 0; // Success
}

