#define GPIO_NUM_18 18
#define GPIO_NUM_27 27

int main() {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error initializing libgpiod: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Open GPIO controllers
    struct gpiod_chip *chip;
    if ((chip = gpiod_get_chip_by_name("bcm2835") == NULL)) {
        fprintf(stderr, "Error: BCM2835 chip not found.\n");
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIOs
    int fd_gpio18 = gpiod_open(chip, GPIO_NUM_18, GPIOD_OPEN_DUPLEX);
    int fd_gpio27 = gpiod_open(chip, GPIO_NUM_27, GPIOD_OPEN_DUPLEX);

    if (fd_gpio18 < 0 || fd_gpio27 < 0) {
        fprintf(stderr, "Error opening GPIOs: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_close(fd_gpio18);
        gpiod_close(fd_gpio27);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set up GPIO 18 and GPIO 27 as outputs
    if (gpiod_direction_output(fd_gpio18, 1) < 0 || gpiod_direction_output(fd_gpio27, 0) < 0) {
        fprintf(stderr, "Error setting GPIO directions: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_close(fd_gpio18);
        gpiod_close(fd_gpio27);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Set GPIO 18 high
        if (gpiod_write(fd_gpio18, 1) < 0) {
            fprintf(stderr, "Error writing to GPIO 18: %s\n", gpiod_errstr(gpiod_get_error()));
            break;
        }

        // Set GPIO 27 low
        if (gpiod_write(fd_gpio27, 0) < 0) {
            fprintf(stderr, "Error writing to GPIO 27: %s\n", gpiod_errstr(gpiod_get_error()));
            break;
        }

        // Sleep for 0.01 seconds
        usleep(10000);

        // Report the state applied
        if (gpiod_get_value(fd_gpio18) == 1) {
            printf("GPIO 18 is HIGH\n");
        } else {
            printf("GPIO 18 is LOW\n");
        }
        if (gpiod_get_value(fd_gpio27) == 0) {
            printf("GPIO 27 is LOW\n");
        } else {
            printf("GPIO 27 is HIGH\n");
        }

        // Check for interrupt (e.g., Ctrl+C)
        if (gpiod_is_closed(fd_gpio18) || gpiod_is_closed(fd_gpio27)) {
            break;
        }
    }

    // Clean up GPIOs and libgpiod
    gpiod_close(fd_gpio18);
    gpiod_close(fd_gpio27);
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

