    if (gpio == -1) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", GPIO_PORT, pigpio_error());
        pigpio_close(0); // Close pigpio if initialization was successful
        return EXIT_FAILURE;
    }

    // Check if the GPIO port is configured as output
    if (pigpio_direction(gpio, pigpio OUTPUT) == -1) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", GPIO_PORT, pigpio_error());
        pigpio_close(gpio); // Close GPIO if direction setting fails
        pigpio_close(0);    // Close pigpio if initialization was successful
        return EXIT_FAILURE;
    }

    // Main loop to set pixel colours in cycles
    for (int cycle = 0; cycle < 3; ++cycle) {
        // Delay for 0.005 seconds
        struct timespec delay = { .tv_sec = 0, .tv_nsec = 5000000 };
        if (nanosleep(&delay, NULL) == -1) {
            fprintf(stderr, "Failed to delay: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        // Set pixel colours
        for (int i = 0; i < NUMPIXELS; ++i) {
            uint32_t color = (i % 256) * 2; // Example: simple gradient from 0 to 255
            if (pigpio_write(gpio, color, 1) == -1) {
                fprintf(stderr, "Failed to write to GPIO %d: %s\n", GPIO_PORT, pigpio_error());
                break; // Exit loop on first error for this cycle
            }
        }
    }

    // Close GPIO port and release resources
    pigpio_close(gpio);

    // Close pigpio library
    pigpio_close(0);

    return EXIT_SUCCESS;
