#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN   23
#define CONTROL_PIN 24

int main() {
    // Initialize libgpiod
    if (gpiod_open() < 0) {
        perror("gpiod_open");
        return EXIT_FAILURE;
    }

    // Initialize GPIO pins
    struct gpiod_dir *trigger_dir = gpiod_get_dir(gpiod_get_device(), TRIGGER_PIN);
    struct gpiod_set_value *trigger_set = gpiod_get_set_value(trigger_dir);
    struct gpiod_dir *echo_dir = gpiod_get_dir(gpiod_get_device(), ECHO_PIN);
    struct gpiod_set_value *echo_set = gpiod_get_set_value(echo_dir);
    struct gpiod_dir *control_dir = gpiod_get_dir(gpiod_get_device(), CONTROL_PIN);
    struct gpiod_set_value *control_set = gpiod_get_set_value(control_dir);

    // Set trigger pin to output
    if (gpiod_set_value(trigger_set, GPIOD_OUTPUT_ONESHOT) < 0) {
        perror("gpiod_set_value (trigger output)");
        gpiod_put_dir(trigger_dir, NULL);
        gpiod_put_dir(echo_dir, NULL);
        gpiod_put_dir(control_dir, NULL);
        gpiod_close();
        return EXIT_FAILURE;
    }

    // Set echo pin to input
    if (gpiod_set_value(echo_set, GPIOD_INPUT) < 0) {
        perror("gpiod_set_value (echo input)");
        gpiod_put_dir(trigger_dir, NULL);
        gpiod_put_dir(echo_dir, NULL);
        gpiod_put_dir(control_dir, NULL);
        gpiod_close();
        return EXIT_FAILURE;
    }

    // Set control pin to output
    if (gpiod_set_value(control_set, GPIOD_OUTPUT_LOW) < 0) {
        perror("gpiod_set_value (control output low)");
        gpiod_put_dir(trigger_dir, NULL);
        gpiod_put_dir(echo_dir, NULL);
        gpiod_put_dir(control_dir, NULL);
        gpiod_close();
        return EXIT_FAILURE;
    }

    // Function to trigger the ultrasonic sensor and read the echo
    void send_trigger() {
        gpiod_set_value(trigger_set, GPIOD_OUTPUT_LOW);
        usleep(2); // Wait for 2 microseconds
        gpiod_set_value(trigger_set, GPIOD_OUTPUT_HIGH);
        usleep(10); // Wait for 10 microseconds
        gpiod_set_value(trigger_set, GPIOD_OUTPUT_LOW);
    }

    void read_echo() {
        int echo_time = 0;
        gpiod_set_value(echo_set, GPIOD_INPUT);
        usleep(1000); // Wait for at least 1 millisecond for echo to settle
        echo_time = gpiod_get_value(echo_set);
        gpiod_set_value(echo_set, GPIOD_INPUT_PULL_UP);

        // Check if echo detected
        if (echo_time > 0) {
            printf("Triggered! Echo detected.\n");
        } else {
            printf("Triggered! No echo detected.\n");
        }
    }

    // Main loop
    while (1) {
        send_trigger();
        read_echo();
        usleep(10000); // Wait for 10 milliseconds
    }

    // Cleanup on interrupt (e.g., Ctrl+C)
    if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
        perror("Setting signal handler");
        return EXIT_FAILURE;
    }

    signal(SIGINT, SIG_DFL); // Restore default signal handler

    // Release resources
    gpiod_put_dir(trigger_dir, NULL);
    gpiod_put_dir(echo_dir, NULL);
    gpiod_put_dir(control_dir, NULL);
    gpiod_close();

    return EXIT_SUCCESS;
}

