// Function to initialize pigpio library
void setup_pigpio() {
    if (pigpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to apply PWM to a specified GPIO pin with a given duty cycle
void apply_pwm(int gpio, int duty_cycle) {
    if (pigpio_set_PWM(gpio, duty_cycle) == -1) {
        fprintf(stderr, "Failed to set PWM on GPIO %d: %s\n", gpio, pigpio_error());
        exit(EXIT_FAILURE);
    }
}

// Function to check the state of a PWM output and report it
void check_and_report_state(int gpio) {
    int state;
    if (pigpio_get_PWM(gpio, &state) == -1) {
        fprintf(stderr, "Failed to get PWM state for GPIO %d: %s\n", gpio, pigpio_error());
        return;
    }

    // Validity check: PWM state should be between 0 and 100
    if (state < 0 || state > 100) {
        fprintf(stderr, "Invalid PWM state for GPIO %d: %d\n", gpio, state);
        return;
    }

    printf("GPIO %d: PWM state = %d%%\n", gpio, state);
}

// Function to clean up resources and exit
void cleanup() {
    pigpio_cleanup();
    exit(EXIT_SUCCESS);
}

