// Function to initialize pigpio library
void setup_pigpio() {
    if (pgpio_init() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return;
    }

    // Set up GPIO pins for PWM
    int gpio_4 = pgpio_open(4, PGPIO_CDT_PWM);
    if (gpio_4 == -1) {
        fprintf(stderr, "Failed to open GPIO 4 for PWM: %s\n", pigpio_error());
        pgpio_close(gpio_4);
        return;
    }

    int gpio_17 = pgpio_open(17, PGPIO_CDT_PWM);
    if (gpio_17 == -1) {
        fprintf(stderr, "Failed to open GPIO 17 for PWM: %s\n", pigpio_error());
        pgpio_close(gpio_17);
        pgpio_close(gpio_4);
        return;
    }

    int gpio_18 = pgpio_open(18, PGPIO_CDT_PWM);
    if (gpio_18 == -1) {
        fprintf(stderr, "Failed to open GPIO 18 for PWM: %s\n", pigpio_error());
        pgpio_close(gpio_18);
        pgpio_close(gpio_17);
        pgpio_close(gpio_4);
        return;
    }

    int gpio_27 = pgpio_open(27, PGPIO_CDT_PWM);
    if (gpio_27 == -1) {
        fprintf(stderr, "Failed to open GPIO 27 for PWM: %s\n", pigpio_error());
        pgpio_close(gpio_27);
        pgpio_close(gpio_18);
        pgpio_close(gpio_17);
        pgpio_close(gpio_4);
        return;
    }

    // Store GPIO handles for later use
    int pwm_gpios[4] = {gpio_4, gpio_17, gpio_18, gpio_27};
}

// Function to apply PWM duty cycle to a GPIO pin
void apply_pwm(int gpio, int duty_cycle) {
    if (pgpio_set_PWM_duty(gpio, duty_cycle) == -1) {
        fprintf(stderr, "Failed to set PWM duty cycle on %d: %s\n", gpio, pigpio_error());
        pgpio_close(gpio);
        return;
    }
    printf("Applied PWM duty cycle %d to GPIO %d\n", duty_cycle, gpio);
}

// Function to cleanup resources and exit
void cleanup_pigpio() {
    for (int i = 0; i < 4; ++i) {
        pgpio_close(pwm_gpios[i]);
    }
    pgpio_cleanup();
}

// Main control loop that runs for 5 cycles, each cycle lasting 60 seconds
void main_loop(int cycles_remaining) {
    if (cycles_remaining <= 0) {
        return;
    }

    // Apply PWM to each GPIO pin in sequence
    for (int i = 0; i < 4; ++i) {
        apply_pwm(pwm_gpios[i], 50); // Example duty cycle of 50%
        sleep(60); // Wait for 60 seconds
    }

    // Decrement the cycle count and continue if there are more cycles to run
    main_loop(cycles_remaining - 1);
}

