#define MAX31855_DEVICE "/dev/spidev0.0" // Adjust for your SPI device path

#define MAX31855_REG_COMMAND 0x00
#define MAX31855_REG_STATUS 0x01
#define MAX31855_REG_DATAHI 0x02
#define MAX31855_REG_DATALO 0x03

#define MAX31855_ADDR 0x10 // Address for MAX31855

// Function prototypes
int spi_open_device(const char *device_path);
void spi_close_device(int fd);
int spi_write(int fd, uint8_t reg, uint16_t value);
int spi_read(int fd, uint8_t reg, uint16_t *value);

// MAX31855 configuration and reading function
int read_temperature_from_max31855(int fd) {
    uint16_t datahi, datalow;
    int ret;

    // Write command to read temperature
    ret = spi_write(fd, MAX31855_REG_COMMAND, MAX31855_ADDR | 0x00);
    if (ret != 0) {
        fprintf(stderr, "Error writing to MAX31855: %s\n", strerror(errno));
        return -1;
    }

    // Read status register
    ret = spi_read(fd, MAX31855_REG_STATUS, &datahi);
    if (ret != 0) {
        fprintf(stderr, "Error reading from MAX31855: %s\n", strerror(errno));
        return -1;
    }

    // Combine datahi and datalow to get the temperature
    datalow = spi_read(fd, MAX31855_REG_DATALO, &datalow);
    uint32_t temperature = (uint32_t)datahi << 16 | datalow;

    // Convert temperature from 12-bit to Celsius
    temperature = (temperature * 0.25) - 500;

    printf("Temperature: %.2f°C\n", temperature);

    return 0;
}

int main() {
