    }

    // Attempt to read temperature
    ret = read_temperature_from_max31855(fd);
    if (ret != 0) {
        fprintf(stderr, "Error reading temperature from MAX31855: %s\n", strerror(errno));
        spi_close_device(fd); // Close SPI device on error
        return 1; // Exit non-zero on error
    }

    // Close SPI device on successful exit
    spi_close_device(fd);

    return 0;
}

