int spi_open_device(const char *device_path) {
    int fd;
    struct spi_device *spi;

    fd = open(device_path, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    spi = gpiod_spi_open(fd, GPIOD_SPI_MODE_0, 1000000); // Assuming 1MHz clock
    if (spi == NULL) {
        fprintf(stderr, "Failed to open SPI device: %s\n", gpiod_error_string(gpiod_get_error()));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to close SPI device
