    gpiod_spi_close(fd);
    close(fd);
}

// Function to write to SPI device
int spi_write(int fd, uint8_t reg, uint16_t value) {
    struct spi_ioc_transfer tx[] = {
        { .tx_buf = (unsigned long)&value, .len = sizeof(value), },
        { .tx_buf = (unsigned long)&reg, .len = 1, .delay_usecs = 0, },
    };

    int ret = gpiod_spi_transfer(fd, tx, 2);
    if (ret < 0) {
        fprintf(stderr, "Error writing to SPI device: %s\n", gpiod_error_string(gpiod_get_error()));
        return ret;
    }

    return 0;
}

// Function to read from SPI device
int spi_read(int fd, uint8_t reg, uint16_t *value) {
    struct spi_ioc_transfer rx[] = {
        { .rx_buf = (unsigned long)*value, .len = sizeof(*value), },
        { .rx_buf = (unsigned long)&reg, .len = 1, .delay_usecs = 0, },
    };

    int ret = gpiod_spi_transfer(fd, rx, 2);
    if (ret < 0) {
        fprintf(stderr, "Error reading from SPI device: %s\n", gpiod_error_string(gpiod_get_error()));
        return ret;
    }

    return 0;
}

