    struct gpiod_dir *echo_dir = gpiod_get_dir(gpiod_get_device(), ECHO_PIN);
    struct gpiod_set_value *echo_set = gpiod_get_set_value(echo_dir);
    struct gpiod_dir *control_dir = gpiod_get_dir(gpiod_get_device(), CONTROL_PIN);
    struct gpiod_set_value *control_set = gpiod_get_set_value(control_dir);
    struct gpiod_dir *power_dir = gpiod_get_dir(gpiod_get_device(), POWER_PIN);
    struct gpiod_set_value *power_set = gpiod_get_set_value(power_dir);

    // Set trigger pin to output
    if (gpiod_set_value(trigger_set, GPIOD_OUTPUT) < 0) {
        perror("gpiod_set_value (trigger output)");
        gpiod_put_dir(trigger_dir, NULL);
        gpiod_put_dir(echo_dir, NULL);
        gpiod_put_dir(control_dir, NULL);
        gpiod_put_dir(power_dir, NULL);
        return EXIT_FAILURE;
    }

    // Set echo pin to input
    if (gpiod_set_value(echo_set, GPIOD_INPUT) < 0) {
        perror("gpiod_set_value (echo input)");
        gpiod_put_dir(trigger_dir, NULL);
        gpiod_put_dir(control_dir, NULL);
        gpiod_put_dir(power_dir, NULL);
        return EXIT_FAILURE;
    }

    // Set control pin to output
    if (gpiod_set_value(control_set, GPIOD_OUTPUT) < 0) {
        perror("gpiod_set_value (control output)");
        gpiod_put_dir(trigger_dir, NULL);
        gpiod_put_dir(echo_dir, NULL);
        gpiod_put_dir(power_dir, NULL);
        return EXIT_FAILURE;
    }

    // Set power pin to output and high
    if (gpiod_set_value(power_set, GPIOD_OUTPUT | GPIOD_HIGH) < 0) {
        perror("gpiod_set_value (power output high)");
        gpiod_put_dir(trigger_dir, NULL);
        gpiod_put_dir(echo_dir, NULL);
        gpiod_put_dir(control_dir, NULL);
        return EXIT_FAILURE;
    }

    // Send trigger pulse
    gpiod_set_value(trigger_set, GPIOD_HIGH);
    usleep(2 * 1000); // 2ms pulse
    gpiod_set_value(trigger_set, GPIOD_LOW);

    // Wait for echo pulse
    while (1) {
        if (gpiod_get_value(echo_set) == GPIOD_LOW) {
