int main() {
    int fd;
    int rc;
    uint8_t buf[6];
    int temp, pressure;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Check if device is present
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDRESS) == -1) {
        perror("Failed to access I2C slave");
        close(fd);
        return EXIT_FAILURE;
    }

    // Perform BMP280 initialization
    buf[0] = BMP280_REG_PRESSURE;
    buf[1] = 0x00; // Write command for pressure
    rc = write(fd, buf, 2);
    if (rc != 2) {
        perror("Failed to write to BMP280");
        close(fd);
        return EXIT_FAILURE;
    }

    // Read pressure
    rc = read(fd, buf, 4);
    if (rc != 4) {
        perror("Failed to read BMP280 pressure");
        close(fd);
        return EXIT_FAILURE;
    }
    pressure = (buf[0] << 8) | buf[1];
    printf("Pressure: %.2f hPa\n", pressure / 100.0);

    // Read temperature
    buf[0] = BMP280_REG_TEMP;
    rc = write(fd, buf, 1);
    if (rc != 1) {
        perror("Failed to write to BMP280");
        close(fd);
        return EXIT_FAILURE;
    }

    // Read temperature
    rc = read(fd, buf, 5);
    if (rc != 5) {
        perror("Failed to read BMP280 temperature");
        close(fd);
        return EXIT_FAILURE;
    }
    temp = (buf[0] << 8) | buf[1];
    printf("Temperature: %.2f °C\n", temp / 100.0);

    // Perform BMP280 shutdown
    buf[0] = BMP280_REG_CONTROL;
    buf[1] = 0x06; // Write control register with shutdown command
    rc = write(fd, buf, 2);
    if (rc != 2) {
        perror("Failed to write to BMP280 control register");
        close(fd);
        return EXIT_FAILURE;
    }

    // Close I2C device
    close(fd);

    // Exit with success
    return EXIT_SUCCESS;
}

