#define BME280_REGISTER_PRESSURE_LOW Byte    : 8
#define BME280_REGISTER_TEMP_HIGH Byte    : 8
#define BME280_REGISTER_TEMP_LOW Byte    : 8
#define BME280_REGISTERhumidity_HIGH Byte : 8
#define BME280_REGISTERhumidity_LOW Byte : 8

