        perror("bme280_write config register");
        bme280_close(fd);
        return 1; // Exit with error if write fails
    }

    // Perform 3 readings with 5 seconds interval
    for (int i = 0; i < 3; ++i) {
        // Read pressure data
        if (bme280_read(fd, BME280_REGISTER_PRESSURE_HIGH, pressure) != 0 ||
            bme280_read(fd, BME280_REGISTER_PRESSURE_LOW, pressure + 1) != 0) {
            perror("bme280_read pressure");
            bme280_close(fd);
            return 1; // Exit with error if read fails
        }

        // Calculate pressure value
        int pressure_value = (pressure[0] << 8) | pressure[1];
        printf("Pressure: %.2f hPa\n", pressure_value / 100.0);

        // Read temperature data
        if (bme280_read(fd, BME280_REGISTER_TEMP_HIGH, temperature) != 0 ||
