        int temperature_value = (temperature[0] << 8) | temperature[1];
        printf("Temperature: %.2f °C\n", temperature_value / 100.0);

        // Read humidity data
        if (bme280_read(fd, BME280_REGISTER_HUMIDITY_HIGH, humidity) != 0 ||
            bme280_read(fd, BME280_REGISTER_HUMIDITY_LOW, humidity + 1) != 0) {
