// Function to write to the BME280 device
int bme280_write(int fd, uint8_t reg_addr, uint8_t value) {
    struct i2c_msg msg = {
        .addr = BME280_I2C_ADDR,
        .flags = 0,
        .len = 1,
        .buf = (void *)reg_addr
    };

    if (i2c_master_send(fd, &msg, 1) != 1) {
        perror("i2c_master_send");
        return -1;
    }

    msg.len = 1;
    msg.buf = &value;
    if (i2c_master_send(fd, &msg, 1) != 1) {
        perror("i2c_master_send");
        return -1;
    }

    return 0;
}

// Function to read from the BME280 device
int bme280_read(int fd, uint8_t reg_addr, uint8_t *data) {
    struct i2c_msg msg = {
        .addr = BME280_I2C_ADDR,
        .flags = 0,
        .len = 2, // 2 bytes to read
        .buf = data
    };

    if (i2c_master_recv(fd, &msg, 2) != 2) {
        perror("i2c_master_recv");
        return -1;
    }

    return 0;
}

// Function to print BME280 data
void print_bme280_data(const uint8_t *data) {
    uint8_t pressure_high = data[BME280_REGISTER_PRESSURE_HIGH];
    uint8_t pressure_low  = data[BME280_REGISTER_PRESSURE_LOW];
    uint8_t temperature_high = data[BME280_REGISTER_TEMP_HIGH];
    uint8_t temperature_low = data[BME280_REGISTER_TEMP_LOW];
    uint8_t humidity_high = data[BME280_REGISTER_HUMIDITY_HIGH];
    uint8_t humidity_low  = data[BME280_REGISTER_HUMIDITY_LOW];

    // Convert data to integer values
    int pressure = (pressure_high << 8) | pressure_low;
    int temperature = (temperature_high << 8) | temperature_low;
    int humidity = (humidity_high << 8) | humidity_low;

    printf("Pressure High: 0x%02X\n", pressure_high);
    printf("Pressure Low:  0x%02X\n", pressure_low);
    printf("Temperature High: 0x%02X\n", temperature_high);
    printf("Temperature Low: 0x%02X\n", temperature_low);
    printf("Humidity High: 0x%02X\n", humidity_high);
    printf("Humidity Low:  0x%02X\n", humidity_low);

    // Calculate and print the actual values
    printf("Pressure: %.2f hPa\n", pressure / 100.0);
    printf("Temperature: %.2f °C\n", temperature / 100.0);
    printf("Humidity: %.2f %%\n", humidity / 100.0);
}

