    // Initialize libgpiod
    if (gpiod_open() < 0) {
        perror("gpiod_open");
        return EXIT_FAILURE;
    }

    // Initialize GPIO pins
    struct gpiod_dir *trigger_dir = gpiod_get_dir(gpiod_get_device(), TRIGGER_PIN);
    struct gpiod_dir *echo_dir = gpiod_get_dir(gpiod_get_device(), ECHO_PIN);

    if (gpiod_direction_output(trigger_dir, 1) < 0 || gpiod_direction_output(echo_dir, 0) < 0) {
        perror("gpiod_direction_output");
        gpiod_close();
        return EXIT_FAILURE;
    }

    // Function to send trigger pulse and read echo
    int read_distance() {
        int start_time, end_time;
        int distance;

        // Send trigger pulse
        gpiod_set_value(trigger_dir, 0);
        usleep(2 * 1000); // 2ms delay
        gpiod_set_value(trigger_dir, 1);

        // Wait for echo
        start_time = usec();
        while (gpiod_get_value(echo_dir) == 0) {
            if (usleep(1000) > 5000) {
                // Timeout, device not responding
                return -1; // Return error code
            }
        }
        end_time = usec();

        // Calculate distance
        distance = (end_time - start_time) / 58; // Assuming speed of sound in air (approx. 343 m/s)

        return distance;
    }

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance != -1) {
            printf("Distance: %.2f cm\n", distance * 100.0);
        } else {
            printf("Failed to read distance\n");
        }

        // Sleep for 0.5 seconds
        usleep(500000);
    }

    // Clean up
    gpiod_set_value(trigger_dir, 0);
    gpiod_set_value(echo_dir, 0);
    gpiod_unexport_all();
    gpiod_close();

    return EXIT_SUCCESS;
}

