        if (!dir) {
            fprintf(stderr, "Failed to open GPIO %s: %s\n", pin_name, gpiod_errstr(gpiod_get_error()));
            gpiod_cleanup(); // Release resources
            return EXIT_FAILURE;
        }

        // Set the GPIO pin to output mode
        if (gpiod_set_direction(dir, GPIOD_OUTPIN) < 0) {
            fprintf(stderr, "Failed to set GPIO %s to output: %s\n", pin_name, gpiod_errstr(gpiod_get_error()));
            gpiod_cleanup(); // Release resources
            return EXIT_FAILURE;
        }

        // Toggle the GPIO pin state
        cand = gpiod_get_cand(dir);
        if (cand) {
            if (gpiod_get_value(cand) == 0) {
                gpiod_set_value(cand, 1);
            } else {
                gpiod_set_value(cand, 0);
            }
