// Function to read data from TCS34725
int read_tcs34725(int fd) {
    uint8_t command = 0x00; // Start command
    uint8_t register_address = 0x00; // Address of the register to read

    // Write command and register address to the TCS34725
    if (write(fd, &command, 1) != 1 || write(fd, &register_address, 1) != 1) {
        perror("Error writing to TCS34725");
        return -1;
    }

    // Read data from the TCS34725
    if (read(fd, &data, 2) != 2) {
        perror("Error reading from TCS34725");
        return -1;
    }

    return 0;
}

