#define SERIAL_PORT "/dev/ttyAMA0" // Adjust according to your Raspberry Pi's serial port

int main() {
    int fd = -1;
    struct termios options;
    char buffer[256];
    int bytes_read;
    int status = 0;

    // Open the serial port
    fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Failed to open serial port");
        exit(1);
    }

    // Get the current terminal settings
    tcgetattr(fd, &options);

    // Set the terminal options (no input/output processing, 8N1)
    options.c_cflag = (options.c_cflag & ~CSIZE) | CS8;
    options.c_cflag |= CLOCAL | CREAD;
    options.c_lflag &= ~(ICANON | ECHO);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);

    // Set the new terminal attributes
    tcsetattr(fd, TCSANOW, &options);

    while (1) {
        // Read data from the serial port
        bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            perror("Error reading from serial port");
            status = 1;
            break;
        }

        // Print the received data
        printf("Received: %s\n", buffer);

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Close the serial port and restore original settings
    tcsetattr(fd, TCSAFLUSH, &options);
    close(fd);

    return status;
}

