        perror("gpiod_open");
        return EXIT_FAILURE;
    }

    // Initialize GPIO pins
    struct gpiod_dir *trigger_dir = gpiod_get_dir(gpiod_get_device(), TRIGGER_PIN);
    struct gpiod_set *trigger_set = gpiod_get_set(trigger_dir);
    gpiod_set_value(trigger_set, GPIOD_OUT_HIGH);

    struct gpiod_dir *echo_dir = gpiod_get_dir(gpiod_get_device(), ECHO_PIN);
    struct gpiod_set *echo_set = gpiod_get_set(echo_dir);
    gpiod_set_value(echo_set, GPIOD_OUT_LOW);

    struct gpiod_dir *control_dir = gpiod_get_dir(gpiod_get_device(), CONTROL_PIN);
    struct gpiod_set *control_set = gpiod_get_set(control_dir);
    gpiod_set_value(control_set, GPIOD_OUT_LOW); // Assuming control pin is active low

    // Send trigger pulse
    usleep(2 * 1000); // 2ms delay
    gpiod_set_value(trigger_set, GPIOD_OUT_LOW);

    // Wait for echo pulse
    unsigned long start_time = microsecond();
    while (microsecond() - start_time < 10000) { // 10ms timeout
        if (gpiod_get_value(echo_set) == GPIOD_IN_HIGH) {
            printf("Echo detected\n");
            break;
        }
        usleep(1000); // Poll every 1ms
    }

    // If no echo detected within timeout, report failure
    if (microsecond() - start_time >= 10000) {
        printf("No echo detected\n");
    }

    // Release GPIO pins
    gpiod_set_value(trigger_set, GPIOD_OUT_LOW);
    gpiod_set_value(echo_set, GPIOD_OUT_LOW);
    gpiod_set_value(control_set, GPIOD_OUT_LOW);

    // Close libgpiod
    gpiod_close();

    return EXIT_SUCCESS;
}

