#define REG_GYRO_YOUT_L 0x47
#define REG_GYRO_ZOUT_H 0x4B
#define REG_GYRO_ZOUT_L 0x4B

// Structure to hold sensor data
typedef struct {
    int16_t accl_x;
    int16_t accl_y;
    int16_t accl_z;
    int16_t gyro_x;
    int16_t gyro_y;
    int16_t gyro_z;
} mpu6050_data;

// Function to read data from MPU6050
int read_mpu6050_data(int fd) {
    uint8_t registerAddress[2] = { REG_ACCEL_XOUT_H, REG_ACCEL_XOUT_L };
    uint8_t registerBuffer[2];
    int ret;

    ret = write(fd, registerAddress, sizeof(registerAddress));
    if (ret != sizeof(registerAddress)) {
        perror("Error writing to register address");
        return -1;
    }

    ret = read(fd, registerBuffer, sizeof(registerBuffer));
    if (ret != sizeof(registerBuffer)) {
        perror("Error reading data");
        return -1;
    }

    int16_t accl_x = (registerBuffer[0] << 8) | registerBuffer[1];
    int16_t accl_y = (registerBuffer[2] << 8) | registerBuffer[3];
    int16_t accl_z = (registerBuffer[4] << 8) | registerBuffer[5];

    registerAddress[0] = REG_GYRO_XOUT_H;
    registerAddress[1] = REG_GYRO_XOUT_L;
    ret = write(fd, registerAddress, sizeof(registerAddress));
    if (ret != sizeof(registerAddress)) {
        perror("Error writing to register address");
        return -1;
    }

    ret = read(fd, registerBuffer, sizeof(registerBuffer));
    if (ret != sizeof(registerBuffer)) {
        perror("Error reading data");
        return -1;
    }

    int16_t gyro_x = (registerBuffer[0] << 8) | registerBuffer[1];
    int16_t gyro_y = (registerBuffer[2] << 8) | registerBuffer[3];
    int16_t gyro_z = (registerBuffer[4] << 8) | registerBuffer[5];

    mpu6050_data data = { accl_x, accl_y, accl_z, gyro_x, gyro_y, gyro_z };
    return 0;
}

int main() {
    int fd;
    mpu6050_data data;

    // Open I2C device
    fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    // Check if device is ready
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Error accessing I2C slave");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read data from the sensor
        if (read_mpu6050_data(fd) != 0) {
            perror("Error reading from MPU6050");
            break;
        }

        // Print sensor data
        printf("Acceleration (g): X=%d, Y=%d, Z=%d\n", data.accl_x, data.accl_y, data.accl_z);
        printf("Rotation (°/s): X=%d, Y=%d, Z=%d\n", data.gyro_x, data.gyro_y, data.gyro_z);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C device and release resources
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define GPIO_NUM 17  // BCM GPIO 17

int main(void) {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        return EXIT_FAILURE;
    }

    // Open GPIO 17 in output mode
    struct gpiod_dir gpio_dir;
    gpio_dir.direction = GPIOD_DIR_OUT_INIT_LOW;
    if (gpiod_request_gpio(GPIO_NUM) < 0) {
        perror("gpiod_request_gpio");
        gpiod_uninit();
        return EXIT_FAILURE;
    }
    if (gpiod_direction_output(GPIO_NUM, 1) < 0) {
        perror("gpiod_direction_output");
        gpiod_release_gpio(GPIO_NUM);
        gpiod_uninit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Toggle the GPIO state
        int state = !gpio_get_value(GPIO_NUM);
        printf("GPIO %d state: %d\n", GPIO_NUM, state);

        // Sleep for 0.6 seconds
        usleep(600000);
    }

    // Release the GPIO on exit
    gpiod_release_gpio(GPIO_NUM);
    gpiod_uninit();

    return EXIT_SUCCESS;
}

